-- Section
-- ============================================================

local Section = {}
Section.__index = Section

function Tab:AddSection(name)
    local outer = new("Frame", {
        Parent = self._page,
        BackgroundColor3 = THEME.Panel,
        Size = UDim2.new(1, -4, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BorderSizePixel = 0,
    })
    corner(8, outer)
    stroke(THEME.Stroke, 1, outer)

    local header = new("Frame", {
        Parent = outer,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 26),
    })
    local headerBtn = new("TextButton", {
        Parent = header,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 0),
        Font = Enum.Font.GothamBold,
        Text = "  " .. name,
        TextColor3 = THEME.Text,
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
    })
    local body = new("Frame", {
        Parent = outer,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        Position = UDim2.new(0, 0, 0, 26),
    })
    new("UIListLayout", {Parent = body, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 5)})
    new("UIPadding", {Parent = body,
        PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 8),
        PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10),
    })

    local collapsed = false
    headerBtn.MouseButton1Click:Connect(function()
        collapsed = not collapsed
        body.Visible = not collapsed
        headerBtn.Text = (collapsed and "  > " or "  ") .. name
    end)

    return setmetatable({
        _frame = body,
        _outer = outer,
        _window = self._window,
        _name = name,
    }, Section)
end

local function rowFrame(parent, height)
    local row = new("Frame", {
        Parent = parent,
        BackgroundColor3 = THEME.Element,
        Size = UDim2.new(1, 0, 0, height or 30),
        BorderSizePixel = 0,
    })
    corner(5, row)
    return row
end

local function trackComponent(section, label, frame)
    table.insert(section._window._components, {Frame = frame, Label = label})
end

-- ---------- Label ----------

function Section:AddLabel(text)
    local lbl = new("TextLabel", {
        Parent = self._frame,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 18),
        Font = Enum.Font.Gotham,
        Text = text,
        TextColor3 = THEME.SubText,
        TextSize = 12,
        TextXAlignment = Enum.TextXAlignment.Left,
    })
    trackComponent(self, text, lbl)
    return {Set = function(_, t) lbl.Text = t end, Frame = lbl}
end

function Section:AddDivider()
    local d = new("Frame", {
        Parent = self._frame,
        BackgroundColor3 = THEME.Stroke,
        BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 1),
    })
    trackComponent(self, "", d)
    return {Frame = d}
end

-- ---------- Button ----------

function Section:AddButton(text, callback)
    local row = rowFrame(self._frame, 32)
    local btn = new("TextButton", {
        Parent = row,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 0),
        AutoButtonColor = false,
        Font = Enum.Font.GothamMedium,
        Text = text,
        TextColor3 = THEME.Text,
        TextSize = 12,
    })
    btn.MouseEnter:Connect(function() TweenService:Create(row, TI_FAST, {BackgroundColor3 = THEME.ElementHover}):Play() end)
    btn.MouseLeave:Connect(function() TweenService:Create(row, TI_FAST, {BackgroundColor3 = THEME.Element}):Play() end)
    btn.MouseButton1Click:Connect(function()
        if callback then task.spawn(callback) end
    end)
    trackComponent(self, text, row)
    return {Frame = row, SetText = function(_, t) btn.Text = t end}
end

-- ---------- Toggle ----------

function Section:AddToggle(text, default, callback)
    local row = rowFrame(self._frame, 30)
    local state = default and true or false

    new("TextLabel", {
        Parent = row, BackgroundTransparency = 1,
        Position = UDim2.new(0, 12, 0, 0),
        Size = UDim2.new(1, -50, 1, 0),
        Font = Enum.Font.GothamMedium, Text = text, TextColor3 = THEME.Text,
        TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
    })

    local sw = new("Frame", {
        Parent = row, BackgroundColor3 = state and THEME.Accent or THEME.Stroke,
        Position = UDim2.new(1, -36, 0.5, -8),
        Size = UDim2.new(0, 28, 0, 16), BorderSizePixel = 0,
    })
    corner(8, sw)
    local knob = new("Frame", {
        Parent = sw, BackgroundColor3 = THEME.Text,
        Position = UDim2.new(state and 1 or 0, state and -14 or 2, 0.5, -6),
        Size = UDim2.new(0, 12, 0, 12), BorderSizePixel = 0,
    })
    corner(6, knob)

    local function set(v, fire)
        state = v and true or false
        TweenService:Create(sw, TI_FAST, {BackgroundColor3 = state and THEME.Accent or THEME.Stroke}):Play()
        TweenService:Create(knob, TI_FAST, {Position = UDim2.new(state and 1 or 0, state and -14 or 2, 0.5, -6)}):Play()
        if fire and callback then task.spawn(callback, state) end
    end

    local clickArea = new("TextButton", {Parent = row, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), Text = ""})
    clickArea.MouseButton1Click:Connect(function() set(not state, true) end)
    if state and callback then task.spawn(callback, true) end

    trackComponent(self, text, row)
    return {Set = function(_, v) set(v, true) end, Get = function() return state end, Frame = row}
end

-- ---------- Slider ----------

function Section:AddSlider(text, min, max, default, callback, opts)
    opts = opts or {}
    local decimals = opts.Decimals or 0
    local row = rowFrame(self._frame, 50)
    local value = default or min

    local label = new("TextLabel", {
        Parent = row, BackgroundTransparency = 1,
        Position = UDim2.new(0, 12, 0, 4),
        Size = UDim2.new(1, -70, 0, 16),
        Font = Enum.Font.GothamMedium, Text = text, TextColor3 = THEME.Text,
        TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
    })

    local inputBox = new("TextBox", {
        Parent = row, BackgroundColor3 = THEME.Panel2,
        Position = UDim2.new(1, -54, 0, 4),
        Size = UDim2.new(0, 44, 0, 16),
        Font = Enum.Font.GothamMedium,
        Text = tostring(value),
        TextColor3 = THEME.Text, TextSize = 11, BorderSizePixel = 0,
        ClearTextOnFocus = false,
    })
    corner(4, inputBox)

    local bar = new("Frame", {
        Parent = row, BackgroundColor3 = THEME.Stroke,
        Position = UDim2.new(0, 12, 1, -16),
        Size = UDim2.new(1, -24, 0, 6),
        BorderSizePixel = 0,
    })
    corner(3, bar)
    local fill = new("Frame", {
        Parent = bar, BackgroundColor3 = THEME.Accent,
        Size = UDim2.new((value - min) / (max - min), 0, 1, 0),
        BorderSizePixel = 0,
    })
    corner(3, fill)

    local function format(v)
        if decimals > 0 then
            local m = 10 ^ decimals
            return tostring(math.floor(v * m + 0.5) / m)
        end
        return tostring(math.floor(v + 0.5))
    end

    local function set(v, fire)
        v = math.clamp(v, min, max)
        if decimals > 0 then
            local m = 10 ^ decimals
            value = math.floor(v * m + 0.5) / m
        else
            value = math.floor(v + 0.5)
        end
        fill.Size = UDim2.new((value - min) / (max - min), 0, 1, 0)
        label.Text = text
        inputBox.Text = format(value)
        if fire and callback then task.spawn(callback, value) end
    end

    inputBox.FocusLost:Connect(function(enter)
        local n = tonumber(inputBox.Text)
        if n then set(n, true) else inputBox.Text = format(value) end
    end)

    local dragging = false
    bar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then dragging = true end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement
                       or input.UserInputType == Enum.UserInputType.Touch) then
            local rel = (input.Position.X - bar.AbsolutePosition.X) / bar.AbsoluteSize.X
            set(min + rel * (max - min), true)
        end
    end)

    if callback then task.spawn(callback, value) end
    trackComponent(self, text, row)
    return {
        Set = function(_, v) set(v, true) end,
        Get = function() return value end,
        Frame = row,
    }
end

-- ---------- Dropdown ----------

function Section:AddDropdown(text, options, default, callback, opts)
    opts = opts or {}
    local multi = opts.Multi
    local row = rowFrame(self._frame, 30)

    new("TextLabel", {
        Parent = row, BackgroundTransparency = 1,
        Position = UDim2.new(0, 12, 0, 0),
        Size = UDim2.new(0.45, 0, 1, 0),
        Font = Enum.Font.GothamMedium, Text = text, TextColor3 = THEME.Text,
        TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
    })

    local valueBtn = new("TextButton", {
        Parent = row, BackgroundColor3 = THEME.Panel2,
        Position = UDim2.new(0.45, 0, 0.5, -10),
        Size = UDim2.new(0.55, -12, 0, 20),
        AutoButtonColor = false,
        Font = Enum.Font.Gotham, Text = "",
        TextColor3 = THEME.Text, TextSize = 11, BorderSizePixel = 0,
    })
    corner(4, valueBtn)

    local current
    if multi then
        current = {}
        if type(default) == "table" then
            for _, v in ipairs(default) do current[v] = true end
        end
    else
        current = default or options[1]
    end

    local function refreshLabel()
        if multi then
            local list = {}
            for k, v in pairs(current) do if v then table.insert(list, tostring(k)) end end
            valueBtn.Text = #list > 0 and table.concat(list, ", ") or "(none)"
        else
            valueBtn.Text = tostring(current) .. "  v"
        end
    end

    local menu = new("Frame", {
        Parent = row, BackgroundColor3 = THEME.Panel,
        Position = UDim2.new(0.45, 0, 1, 4),
        Size = UDim2.new(0.55, -12, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        Visible = false, ZIndex = 20, BorderSizePixel = 0,
    })
    corner(5, menu)
    stroke(THEME.Stroke, 1, menu)
    new("UIListLayout", {Parent = menu, SortOrder = Enum.SortOrder.LayoutOrder})

    local function rebuildItems(newOptions)
        for _, child in ipairs(menu:GetChildren()) do
            if child:IsA("TextButton") then child:Destroy() end
        end
        for _, opt in ipairs(newOptions) do
            local item = new("TextButton", {
                Parent = menu, BackgroundColor3 = THEME.Panel,
                Size = UDim2.new(1, 0, 0, 22),
                AutoButtonColor = false,
                Font = Enum.Font.Gotham, Text = "  " .. tostring(opt),
                TextColor3 = THEME.SubText, TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 21, BorderSizePixel = 0,
            })
            item.MouseEnter:Connect(function() item.BackgroundColor3 = THEME.ElementHover end)
            item.MouseLeave:Connect(function() item.BackgroundColor3 = THEME.Panel end)
            item.MouseButton1Click:Connect(function()
                if multi then
                    current[opt] = not current[opt]
                    item.TextColor3 = current[opt] and THEME.AccentSoft or THEME.SubText
                    refreshLabel()
                    if callback then task.spawn(callback, current) end
                else
                    current = opt
                    refreshLabel()
                    menu.Visible = false
                    if callback then task.spawn(callback, current) end
                end
            end)
            if multi and current[opt] then item.TextColor3 = THEME.AccentSoft end
        end
    end

    rebuildItems(options)
    refreshLabel()

    valueBtn.MouseButton1Click:Connect(function() menu.Visible = not menu.Visible end)

    if callback then task.spawn(callback, current) end
    trackComponent(self, text, row)
    return {
        Set = function(_, v) current = v; refreshLabel(); if callback then task.spawn(callback, current) end end,
        Get = function() return current end,
        SetOptions = function(_, newOpts) rebuildItems(newOpts) end,
        Frame = row,
    }
end

-- ---------- Keybind ----------

function Section:AddKeybind(text, default, callback, opts)
    opts = opts or {}
    local row = rowFrame(self._frame, 30)
    local key = default
    local listening = false

    new("TextLabel", {
        Parent = row, BackgroundTransparency = 1,
        Position = UDim2.new(0, 12, 0, 0),
        Size = UDim2.new(1, -100, 1, 0),
        Font = Enum.Font.GothamMedium, Text = text, TextColor3 = THEME.Text,
        TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
    })

    local btn = new("TextButton", {
        Parent = row, BackgroundColor3 = THEME.Panel2,
        Position = UDim2.new(1, -88, 0.5, -10),
        Size = UDim2.new(0, 78, 0, 20),
        AutoButtonColor = false,
        Font = Enum.Font.Gotham, Text = key and key.Name or "...",
        TextColor3 = THEME.Text, TextSize = 11, BorderSizePixel = 0,
    })
    corner(4, btn)

    btn.MouseButton1Click:Connect(function()
        listening = true; btn.Text = "[press]"
    end)

    UserInputService.InputBegan:Connect(function(input, processed)
        if listening then
            if input.UserInputType == Enum.UserInputType.Keyboard then
                if input.KeyCode == Enum.KeyCode.Backspace then
                    key = nil
                else
                    key = input.KeyCode
                end
                btn.Text = key and key.Name or "..."
                listening = false
            end
            return
        end
        if processed then return end
        if key and input.KeyCode == key and callback then
            task.spawn(callback)
        end
    end)

    trackComponent(self, text, row)
    return {
        Get = function() return key end,
        Set = function(_, k) key = k; btn.Text = k and k.Name or "..." end,
        Frame = row,
    }
end

-- ---------- TextBox ----------

function Section:AddTextBox(text, placeholder, callback)
    local row = rowFrame(self._frame, 30)
    new("TextLabel", {
        Parent = row, BackgroundTransparency = 1,
        Position = UDim2.new(0, 12, 0, 0),
        Size = UDim2.new(0.4, 0, 1, 0),
        Font = Enum.Font.GothamMedium, Text = text, TextColor3 = THEME.Text,
        TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
    })
    local box = new("TextBox", {
        Parent = row, BackgroundColor3 = THEME.Panel2,
        Position = UDim2.new(0.4, 0, 0.5, -10),
        Size = UDim2.new(0.6, -12, 0, 20),
        Font = Enum.Font.Gotham, PlaceholderText = placeholder or "",
        Text = "", TextColor3 = THEME.Text, PlaceholderColor3 = THEME.DimText,
        TextSize = 11, ClearTextOnFocus = false, BorderSizePixel = 0,
    })
    corner(4, box)
    box.FocusLost:Connect(function(enter)
        if callback then task.spawn(callback, box.Text, enter) end
    end)
    trackComponent(self, text, row)
    return {Get = function() return box.Text end, Set = function(_, v) box.Text = v end, Frame = row}
end

-- ---------- Color Picker ----------

function Section:AddColorPicker(text, default, callback)
    local row = rowFrame(self._frame, 30)
    local current = default or Color3.fromRGB(255, 255, 255)

    new("TextLabel", {
        Parent = row, BackgroundTransparency = 1,
        Position = UDim2.new(0, 12, 0, 0),
        Size = UDim2.new(1, -60, 1, 0),
        Font = Enum.Font.GothamMedium, Text = text, TextColor3 = THEME.Text,
        TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
    })

    local swatch = new("TextButton", {
        Parent = row, BackgroundColor3 = current,
        Position = UDim2.new(1, -44, 0.5, -10),
        Size = UDim2.new(0, 34, 0, 20),
        AutoButtonColor = false, Text = "", BorderSizePixel = 0,
    })
    corner(4, swatch)
    stroke(THEME.Stroke, 1, swatch)

    -- Tiny popup with H/S/V sliders. Compact and good enough.
    local popup = new("Frame", {
        Parent = row, BackgroundColor3 = THEME.Panel,
        Position = UDim2.new(1, -210, 1, 4),
        Size = UDim2.new(0, 200, 0, 100),
        Visible = false, ZIndex = 30, BorderSizePixel = 0,
    })
    corner(6, popup); stroke(THEME.Stroke, 1, popup)

    local function makeBar(y, label)
        new("TextLabel", {
            Parent = popup, BackgroundTransparency = 1,
            Position = UDim2.new(0, 10, 0, y),
            Size = UDim2.new(0, 30, 0, 16),
            Font = Enum.Font.GothamMedium, Text = label, TextColor3 = THEME.Text,
            TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 31,
        })
        local bar = new("Frame", {
            Parent = popup, BackgroundColor3 = THEME.Stroke,
            Position = UDim2.new(0, 44, 0, y + 4),
            Size = UDim2.new(0, 130, 0, 8),
            ZIndex = 31, BorderSizePixel = 0,
        })
        corner(4, bar)
        local fill = new("Frame", {
            Parent = bar, BackgroundColor3 = THEME.Accent,
            Size = UDim2.new(0, 0, 1, 0),
            ZIndex = 32, BorderSizePixel = 0,
        })
        corner(4, fill)
        return bar, fill
    end

    local h, s, v = Color3.toHSV(current)
    local hBar, hFill = makeBar(8,  "H")
    local sBar, sFill = makeBar(34, "S")
    local vBar, vFill = makeBar(60, "V")

    local function refresh()
        current = Color3.fromHSV(h, s, v)
        swatch.BackgroundColor3 = current
        hFill.Size = UDim2.new(h, 0, 1, 0)
        sFill.Size = UDim2.new(s, 0, 1, 0)
        vFill.Size = UDim2.new(v, 0, 1, 0)
        if callback then task.spawn(callback, current) end
    end
    refresh()

    local function bind(bar, setter)
        local dragging
        bar.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = true end
        end)
        UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end
        end)
        UserInputService.InputChanged:Connect(function(input)
            if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
                local rel = math.clamp((input.Position.X - bar.AbsolutePosition.X) / bar.AbsoluteSize.X, 0, 1)
                setter(rel); refresh()
            end
        end)
    end
    bind(hBar, function(x) h = x end)
    bind(sBar, function(x) s = x end)
    bind(vBar, function(x) v = x end)

    swatch.MouseButton1Click:Connect(function() popup.Visible = not popup.Visible end)

    if callback then task.spawn(callback, current) end
    trackComponent(self, text, row)
    return {
        Set = function(_, c) current = c; h, s, v = Color3.toHSV(c); refresh() end,
        Get = function() return current end,
        Frame = row,
    }
end

return UI

end

_modules['src/library/notify.lua'] = function()
--[[
    Toast notifications — top-right stack with slide-in from right
    (Back-easing overshoot) and slide-out on dismiss. Each notification
    has an accent strip, drop shadow, and gradient background.
]]

local TweenService = game:GetService("TweenService")
local CoreGui      = game:GetService("CoreGui")

local Notify = {}

local container

local THEME = {
    Bg     = Color3.fromRGB(20, 18, 28),
    Bg2    = Color3.fromRGB(28, 26, 40),
    Accent = Color3.fromRGB(140, 100, 255),
    Text   = Color3.fromRGB(232, 232, 244),
    Sub    = Color3.fromRGB(160, 162, 178),
    Stroke = Color3.fromRGB(60, 56, 84),
}

local function ensureContainer()
    if container and container.Parent then return container end
    local gui = Instance.new("ScreenGui")
    gui.Name = "ROGBLOX_Notify"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder = 500
    if syn and syn.protect_gui then syn.protect_gui(gui) end
    gui.Parent = (gethui and gethui()) or CoreGui

    local list = Instance.new("Frame")
    list.Name = "List"
    list.AnchorPoint = Vector2.new(1, 0)
    list.Position = UDim2.new(1, -16, 0, 16)
    list.Size = UDim2.new(0, 300, 1, -32)
    list.BackgroundTransparency = 1
    list.Parent = gui

    local layout = Instance.new("UIListLayout")
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 8)
    layout.VerticalAlignment = Enum.VerticalAlignment.Top
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Right
    layout.Parent = list

    container = list
    return container
end

function Notify:Send(title, body, duration)
    duration = duration or 3
    local parent = ensureContainer()

    local card = Instance.new("Frame")
    card.AnchorPoint = Vector2.new(1, 0)
    card.BackgroundColor3 = THEME.Bg
    card.BorderSizePixel = 0
    card.Size = UDim2.new(1, 0, 0, 0)
    card.AutomaticSize = Enum.AutomaticSize.Y
    card.BackgroundTransparency = 1
    card.Position = UDim2.new(1, 60, 0, 0)   -- start off-screen right
    card.ClipsDescendants = true
    card.Parent = parent
    Instance.new("UICorner", card).CornerRadius = UDim.new(0, 7)

    -- subtle gradient background
    local grad = Instance.new("UIGradient")
    grad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, THEME.Bg2),
        ColorSequenceKeypoint.new(1, THEME.Bg),
    })
    grad.Rotation = 110
    grad.Parent = card

    local stroke = Instance.new("UIStroke")
    stroke.Color = THEME.Accent
    stroke.Thickness = 1
    stroke.Transparency = 1
    stroke.Parent = card

    -- accent strip on the left
    local strip = Instance.new("Frame")
    strip.BackgroundColor3 = THEME.Accent
    strip.BorderSizePixel = 0
    strip.Position = UDim2.new(0, 0, 0, 6)
    strip.Size = UDim2.new(0, 3, 1, -12)
    strip.Parent = card
    Instance.new("UICorner", strip).CornerRadius = UDim.new(0, 2)

    local pad = Instance.new("UIPadding")
    pad.PaddingTop    = UDim.new(0, 10)
    pad.PaddingBottom = UDim.new(0, 12)
    pad.PaddingLeft   = UDim.new(0, 14)
    pad.PaddingRight  = UDim.new(0, 12)
    pad.Parent = card

    local titleLbl = Instance.new("TextLabel")
    titleLbl.BackgroundTransparency = 1
    titleLbl.Size = UDim2.new(1, 0, 0, 16)
    titleLbl.Font = Enum.Font.GothamBold
    titleLbl.Text = title or ""
    titleLbl.TextColor3 = THEME.Text
    titleLbl.TextTransparency = 1
    titleLbl.TextSize = 13
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl.Parent = card

    local bodyLbl = Instance.new("TextLabel")
    bodyLbl.BackgroundTransparency = 1
    bodyLbl.Position = UDim2.new(0, 0, 0, 20)
    bodyLbl.Size = UDim2.new(1, 0, 0, 0)
    bodyLbl.AutomaticSize = Enum.AutomaticSize.Y
    bodyLbl.Font = Enum.Font.Gotham
    bodyLbl.Text = body or ""
    bodyLbl.TextWrapped = true
    bodyLbl.TextColor3 = THEME.Sub
    bodyLbl.TextTransparency = 1
    bodyLbl.TextSize = 11
    bodyLbl.TextXAlignment = Enum.TextXAlignment.Left
    bodyLbl.Parent = card

    local inT  = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
    local outT = TweenInfo.new(0.30, Enum.EasingStyle.Sine, Enum.EasingDirection.In)

    -- Slide in + fade in
    TweenService:Create(card, inT, {
        Position = UDim2.new(1, 0, 0, 0),
        BackgroundTransparency = 0,
    }):Play()
    TweenService:Create(stroke, inT, {Transparency = 0}):Play()
    TweenService:Create(titleLbl, inT, {TextTransparency = 0}):Play()
    TweenService:Create(bodyLbl, inT, {TextTransparency = 0.05}):Play()

    task.delay(duration, function()
        if not card.Parent then return end
        TweenService:Create(card, outT, {
            Position = UDim2.new(1, 80, 0, 0),
            BackgroundTransparency = 1,
        }):Play()
        TweenService:Create(stroke, outT, {Transparency = 1}):Play()
        TweenService:Create(titleLbl, outT, {TextTransparency = 1}):Play()
        TweenService:Create(bodyLbl, outT, {TextTransparency = 1}):Play()
        task.wait(0.35)
        card:Destroy()
    end)
end

return Notify

end

_modules['src/library/splash.lua'] = function()
--[[
    Startup splash — big centered "ROGBLOX loaded" card that pulses in
    when the hub finishes booting, then fades out after a few seconds.
    Drop-in: Splash.Show("Title", "Body", duration_seconds).
]]

local TweenService = game:GetService("TweenService")
local CoreGui      = game:GetService("CoreGui")

local M = {}

local function makeGui()
    local gui = Instance.new("ScreenGui")
    gui.Name = "ROGBLOX_Splash"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder = 1000
    if syn and syn.protect_gui then syn.protect_gui(gui) end
    gui.Parent = (gethui and gethui()) or CoreGui
    return gui
end

function M.Show(title, body, duration)
    duration = duration or 2.4

    local gui = makeGui()

    local card = Instance.new("Frame")
    card.AnchorPoint = Vector2.new(0.5, 0.5)
    card.Position = UDim2.new(0.5, 0, 0.5, 0)
    card.Size = UDim2.new(0, 340, 0, 110)
    card.BackgroundColor3 = Color3.fromRGB(20, 20, 28)
    card.BackgroundTransparency = 1
    card.BorderSizePixel = 0
    card.Parent = gui
    Instance.new("UICorner", card).CornerRadius = UDim.new(0, 12)

    local s = Instance.new("UIStroke")
    s.Color = Color3.fromRGB(140, 100, 255)
    s.Thickness = 1.5
    s.Transparency = 1
    s.Parent = card

    -- gradient bg
    local grad = Instance.new("UIGradient")
    grad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,  Color3.fromRGB(28, 26, 44)),
        ColorSequenceKeypoint.new(1,  Color3.fromRGB(18, 16, 30)),
    })
    grad.Rotation = 120
    grad.Parent = card

    -- accent strip
    local strip = Instance.new("Frame")
    strip.BackgroundColor3 = Color3.fromRGB(140, 100, 255)
    strip.Position = UDim2.new(0, 12, 0.5, -22)
    strip.Size = UDim2.new(0, 4, 0, 0)
    strip.BorderSizePixel = 0
    strip.Parent = card
    Instance.new("UICorner", strip).CornerRadius = UDim.new(0, 2)

    -- title (gradient text effect via UIGradient on a TextLabel)
    local titleLbl = Instance.new("TextLabel")
    titleLbl.BackgroundTransparency = 1
    titleLbl.Position = UDim2.new(0, 28, 0, 18)
    titleLbl.Size = UDim2.new(1, -44, 0, 30)
    titleLbl.Font = Enum.Font.GothamBold
    titleLbl.Text = title or "ROGBLOX"
    titleLbl.TextColor3 = Color3.fromRGB(245, 240, 255)
    titleLbl.TextSize = 22
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl.TextTransparency = 1
    titleLbl.Parent = card

    local tg = Instance.new("UIGradient")
    tg.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,    Color3.fromRGB(210, 175, 255)),
        ColorSequenceKeypoint.new(0.5,  Color3.fromRGB(140, 100, 255)),
        ColorSequenceKeypoint.new(1,    Color3.fromRGB(255, 130, 200)),
    })
    tg.Parent = titleLbl

    local bodyLbl = Instance.new("TextLabel")
    bodyLbl.BackgroundTransparency = 1
    bodyLbl.Position = UDim2.new(0, 28, 0, 52)
    bodyLbl.Size = UDim2.new(1, -44, 0, 44)
    bodyLbl.Font = Enum.Font.Gotham
    bodyLbl.Text = body or ""
    bodyLbl.TextColor3 = Color3.fromRGB(170, 175, 195)
    bodyLbl.TextSize = 12
    bodyLbl.TextXAlignment = Enum.TextXAlignment.Left
    bodyLbl.TextYAlignment = Enum.TextYAlignment.Top
    bodyLbl.TextWrapped = true
    bodyLbl.TextTransparency = 1
    bodyLbl.Parent = card

    -- starting pose: slightly smaller + invisible, then ease into place
    card.Size = UDim2.new(0, 300, 0, 96)

    local easeIn  = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
    local easeOut = TweenInfo.new(0.30, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)

    TweenService:Create(card, easeIn, {
        BackgroundTransparency = 0.05,
        Size = UDim2.new(0, 340, 0, 110),
    }):Play()
    TweenService:Create(s,        easeIn, {Transparency = 0}):Play()
    TweenService:Create(titleLbl, easeIn, {TextTransparency = 0}):Play()
    TweenService:Create(bodyLbl,  easeIn, {TextTransparency = 0.05}):Play()
    TweenService:Create(strip,    easeIn, {Size = UDim2.new(0, 4, 0, 44)}):Play()

    task.delay(duration, function()
        TweenService:Create(card,     easeOut, {BackgroundTransparency = 1}):Play()
        TweenService:Create(s,        easeOut, {Transparency = 1}):Play()
        TweenService:Create(titleLbl, easeOut, {TextTransparency = 1}):Play()
        TweenService:Create(bodyLbl,  easeOut, {TextTransparency = 1}):Play()
        TweenService:Create(strip,    easeOut, {Size = UDim2.new(0, 4, 0, 0)}):Play()
        task.wait(0.4)
        gui:Destroy()
    end)
end

return M

end

_modules['src/library/savemanager.lua'] = function()
--[[
    SaveManager addon (Linoria pattern).

    Per-PlaceId named profiles, persisted as JSON on disk via the
    executor's filesystem API.

    Storage layout:
        ROGBLOX/
          settings/
            <placeId>/
              <profileName>.json
              autoload.txt        -- name of profile to load on startup

    Each registered "flag" is a {Get, Set} pair backed by a UI component.
    Save() serializes every flag's current value, Load() restores them.
]]

local HttpService = game:GetService("HttpService")

local M = {}

M.Folder       = "ROGBLOX/settings"
M.PlaceFolder  = nil
M.AutoloadPath = nil
M.Flags        = {}     -- [name] = {Get = fn, Set = fn(value), Default = ?}
M.Listeners    = {}
M.Ignore       = {}     -- [name] = true skips on save/load (e.g. theme keys)

-- ---------- Filesystem helpers ----------

local hasFS = type(writefile) == "function"
             and type(readfile)  == "function"
             and type(isfile)    == "function"
             and type(makefolder) == "function"

local function ensureFolders()
    if not hasFS then return false end
    for _, path in ipairs({"ROGBLOX", M.Folder, M.PlaceFolder}) do
        if isfolder and not isfolder(path) then
            pcall(makefolder, path)
        end
    end
    return true
end

local function init()
    M.PlaceFolder = M.Folder .. "/" .. tostring(game.PlaceId)
    M.AutoloadPath = M.PlaceFolder .. "/autoload.txt"
    ensureFolders()
end
init()

-- ---------- Flag registration ----------

function M.Register(name, accessors)
    -- accessors = {Get = function() return v end, Set = function(v) ... end, Default = v}
    M.Flags[name] = accessors
end

function M.Unregister(name)
    M.Flags[name] = nil
end

function M.SetIgnore(name, on)
    M.Ignore[name] = on and true or nil
end

-- ---------- Save / load ----------

function M.Snapshot()
    local out = {}
    for name, accessors in pairs(M.Flags) do
        if not M.Ignore[name] and accessors.Get then
            local ok, value = pcall(accessors.Get)
            if ok then
                -- Color3 -> {hex} for JSON round-trip
                if typeof(value) == "Color3" then
                    out[name] = {kind = "Color3", hex = string.format("#%02x%02x%02x",
                        math.floor(value.R * 255 + 0.5),
                        math.floor(value.G * 255 + 0.5),
                        math.floor(value.B * 255 + 0.5))}
                elseif typeof(value) == "EnumItem" then
                    out[name] = {kind = "Enum", value = tostring(value)}
                elseif type(value) == "table" then
                    out[name] = {kind = "table", value = value}
                else
                    out[name] = value
                end
            end
        end
    end
    return out
end

function M.Apply(data)
    if type(data) ~= "table" then return end
    for name, value in pairs(data) do
        local accessors = M.Flags[name]
        if accessors and accessors.Set then
            local v = value
            if type(value) == "table" and value.kind == "Color3" and value.hex then
                local r = tonumber(value.hex:sub(2, 3), 16) or 0
                local g = tonumber(value.hex:sub(4, 5), 16) or 0
                local b = tonumber(value.hex:sub(6, 7), 16) or 0
                v = Color3.fromRGB(r, g, b)
            elseif type(value) == "table" and value.kind == "table" then
                v = value.value
            end
            pcall(accessors.Set, v)
        end
    end
end

function M.Save(profileName)
    if not hasFS then return false, "no filesystem" end
    profileName = profileName or "default"
    ensureFolders()
    local path = M.PlaceFolder .. "/" .. profileName .. ".json"
    local ok, encoded = pcall(HttpService.JSONEncode, HttpService, M.Snapshot())
    if not ok then return false, encoded end
    local ok2, err = pcall(writefile, path, encoded)
    return ok2, err or path
end

function M.Load(profileName)
    if not hasFS then return false, "no filesystem" end
    profileName = profileName or "default"
    local path = M.PlaceFolder .. "/" .. profileName .. ".json"
    if not (isfile and isfile(path)) then return false, "no such profile" end
    local ok, raw = pcall(readfile, path)
    if not ok then return false, raw end
    local ok2, decoded = pcall(HttpService.JSONDecode, HttpService, raw)
    if not ok2 then return false, decoded end
    M.Apply(decoded)
    return true
end

function M.Delete(profileName)
    if not hasFS then return false end
    local path = M.PlaceFolder .. "/" .. profileName .. ".json"
    if isfile and isfile(path) and delfile then
        pcall(delfile, path)
        return true
    end
    return false
end

function M.List()
    local out = {}
    if not (hasFS and listfiles) then return out end
    local ok, files = pcall(listfiles, M.PlaceFolder)
    if not ok then return out end
    for _, file in ipairs(files) do
        local name = file:match("([^/\\]+)%.json$")
        if name then table.insert(out, name) end
    end
    table.sort(out)
    return out
end

-- ---------- Autoload ----------

function M.SetAutoload(profileName)
    if not hasFS then return end
    if profileName == nil or profileName == "" then
        if isfile and isfile(M.AutoloadPath) and delfile then pcall(delfile, M.AutoloadPath) end
        return
    end
    pcall(writefile, M.AutoloadPath, tostring(profileName))
end

function M.GetAutoload()
    if not hasFS then return nil end
    if isfile and isfile(M.AutoloadPath) then
        local ok, name = pcall(readfile, M.AutoloadPath)
        if ok then return name end
    end
    return nil
end

function M.AutoLoad()
    local name = M.GetAutoload()
    if name and name ~= "" then
        return M.Load(name)
    end
    return false
end

-- ---------- UI binding helpers ----------

-- Helper to wrap a UI component (with :Get / :Set) into a flag.
function M.BindComponent(name, component)
    M.Register(name, {
        Get = function() return component.Get and component:Get() or component:Get() end,
        Set = function(v) if component.Set then component:Set(v) end end,
    })
end

return M

end

