_modules['src/config.lua'] = function()
--[[
    Config persistence
    Stores per-game configs as JSON under workspace/ROGBLOX/<PlaceId>.json.
    Uses writefile/readfile if the executor supports them.
]]

local HttpService = game:GetService("HttpService")

local Config = {}

Config.FOLDER = "ROGBLOX"
Config._values = {}
Config._defaults = {}
Config._listeners = {}

local function has(fn)
    return type(_G[fn]) == "function" or type(rawget(getfenv(), fn)) == "function"
end

local hasFS = pcall(function()
    return writefile and readfile and isfile and makefolder
end) and writefile and readfile and isfile and makefolder

local function placePath()
    return Config.FOLDER .. "/" .. tostring(game.PlaceId) .. ".json"
end

local function ensureFolder()
    if hasFS and makefolder and not (isfolder and isfolder(Config.FOLDER)) then
        pcall(makefolder, Config.FOLDER)
    end
end

function Config.SetDefault(key, value)
    Config._defaults[key] = value
    if Config._values[key] == nil then
        Config._values[key] = value
    end
end

function Config.Get(key)
    if Config._values[key] ~= nil then return Config._values[key] end
    return Config._defaults[key]
end

function Config.Set(key, value)
    Config._values[key] = value
    local list = Config._listeners[key]
    if list then
        for _, fn in ipairs(list) do
            task.spawn(fn, value)
        end
    end
end

function Config.OnChange(key, fn)
    Config._listeners[key] = Config._listeners[key] or {}
    table.insert(Config._listeners[key], fn)
end

function Config.Save()
    if not hasFS then return false, "no filesystem" end
    ensureFolder()
    local ok, encoded = pcall(HttpService.JSONEncode, HttpService, Config._values)
    if not ok then return false, encoded end
    local ok2, err = pcall(writefile, placePath(), encoded)
    return ok2, err
end

function Config.Load()
    if not hasFS then return false, "no filesystem" end
    if not (isfile and isfile(placePath())) then return false, "no config" end
    local ok, raw = pcall(readfile, placePath())
    if not ok then return false, raw end
    local ok2, decoded = pcall(HttpService.JSONDecode, HttpService, raw)
    if not ok2 then return false, decoded end
    for k, v in pairs(decoded) do
        Config.Set(k, v)
    end
    return true
end

function Config.Reset()
    Config._values = {}
    for k, v in pairs(Config._defaults) do
        Config.Set(k, v)
    end
end

function Config.Export()
    local ok, encoded = pcall(HttpService.JSONEncode, HttpService, Config._values)
    return ok and encoded or "{}"
end

function Config.Import(str)
    local ok, decoded = pcall(HttpService.JSONDecode, HttpService, str)
    if not ok then return false, decoded end
    for k, v in pairs(decoded) do
        Config.Set(k, v)
    end
    return true
end

return Config

end

_modules['src/utils/players.lua'] = function()
--[[
    Player utility helpers — iteration, alive checks, distance,
    LOS, and finding the closest target for aimbot.
]]

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")

local M = {}

function M.LocalPlayer()
    return Players.LocalPlayer
end

function M.LocalCharacter()
    local lp = Players.LocalPlayer
    return lp and lp.Character
end

function M.LocalRoot()
    local char = M.LocalCharacter()
    return char and char:FindFirstChild("HumanoidRootPart")
end

function M.GetHumanoid(plr)
    local char = plr and plr.Character
    return char and char:FindFirstChildOfClass("Humanoid")
end

function M.GetRoot(plr)
    local char = plr and plr.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

function M.GetHead(plr)
    local char = plr and plr.Character
    return char and char:FindFirstChild("Head")
end

function M.IsAlive(plr)
    local hum = M.GetHumanoid(plr)
    return hum and hum.Health > 0
end

function M.SameTeam(plr)
    local lp = Players.LocalPlayer
    if not lp or not plr then return false end
    if not lp.Team or not plr.Team then return false end
    return lp.Team == plr.Team
end

function M.Distance(a, b)
    if not a or not b then return math.huge end
    return (a.Position - b.Position).Magnitude
end

-- Line of sight check using Raycast. Accepts either a BasePart or a
-- table with a Position field as the "from".
function M.HasLOS(from, toPart, ignoreList)
    if not from or not toPart then return false end
    local origin = (typeof(from) == "Instance" and from.Position) or from.Position
    if not origin then return false end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local ignore = {M.LocalCharacter()}
    if ignoreList then
        for _, v in ipairs(ignoreList) do table.insert(ignore, v) end
    end
    params.FilterDescendantsInstances = ignore
    local dir = (toPart.Position - origin)
    local result = Workspace:Raycast(origin, dir, params)
    if not result then return true end
    return result.Instance:IsDescendantOf(toPart.Parent)
end

-- Finds the closest player to a screen position (in pixels)
function M.ClosestToScreenPoint(screenPoint, opts)
    opts = opts or {}
    local camera = Workspace.CurrentCamera
    if not camera then return nil end
    local maxFov = opts.MaxFov or 100
    local checkTeam = opts.CheckTeam
    local checkLOS = opts.CheckLOS
    local part = opts.Part or "Head"

    local closest, bestDist
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer and M.IsAlive(plr) then
            if not (checkTeam and M.SameTeam(plr)) then
                local target = plr.Character and plr.Character:FindFirstChild(part)
                if target then
                    local screen, onScreen = camera:WorldToViewportPoint(target.Position)
                    if onScreen then
                        local dx = screen.X - screenPoint.X
                        local dy = screen.Y - screenPoint.Y
                        local dist = math.sqrt(dx * dx + dy * dy)
                        if dist <= maxFov and (not bestDist or dist < bestDist) then
                            if not checkLOS or M.HasLOS({Position = camera.CFrame.Position}, target) then
                                bestDist = dist
                                closest = plr
                            end
                        end
                    end
                end
            end
        end
    end
    return closest
end

function M.ForEachPlayer(fn)
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer then
            task.spawn(fn, plr)
        end
    end
end

return M

end

_modules['src/utils/drawing.lua'] = function()
--[[
    Drawing API wrapper.
    Executors expose Drawing.new("Type") for on-screen shapes that
    bypass Roblox's GUI system. We wrap it to clean up on Remove and
    fall back to BillboardGui when Drawing isn't available.
]]

local M = {}

local hasDrawing = type(Drawing) == "table" and type(Drawing.new) == "function"
M.Supported = hasDrawing

local registry = setmetatable({}, {__mode = "v"})

local function fallback(class, props)
    -- Tiny BillboardGui-based fallback. Crude but keeps the UI alive
    -- on executors without Drawing.
    local part = Instance.new("Part")
    part.Anchored = true
    part.CanCollide = false
    part.Transparency = 1
    part.Size = Vector3.new(0.1, 0.1, 0.1)
    part.Parent = workspace
    local bb = Instance.new("BillboardGui")
    bb.AlwaysOnTop = true
    bb.Size = UDim2.new(0, props.Size and props.Size.X or 50, 0, props.Size and props.Size.Y or 20)
    bb.Parent = part
    local frame = Instance.new(class == "Text" and "TextLabel" or "Frame")
    frame.BackgroundTransparency = class == "Text" and 1 or 0.5
    frame.BackgroundColor3 = props.Color or Color3.new(1, 1, 1)
    frame.Size = UDim2.new(1, 0, 1, 0)
    if class == "Text" then
        frame.Text = props.Text or ""
        frame.TextColor3 = props.Color or Color3.new(1, 1, 1)
        frame.Font = Enum.Font.GothamBold
        frame.TextSize = props.Size or 12
    end
    frame.Parent = bb
    return {
        _part = part, _frame = frame, _fallback = true,
        Remove = function(self)
            if self._part then self._part:Destroy(); self._part = nil end
        end,
        Set = function(self, k, v)
            if k == "Visible" then
                self._part.Parent = v and workspace or nil
            elseif k == "Color" then
                self._frame.BackgroundColor3 = v
                if self._frame:IsA("TextLabel") then self._frame.TextColor3 = v end
            elseif k == "Text" and self._frame:IsA("TextLabel") then
                self._frame.Text = v
            end
        end,
    }
end

function M.new(class, defaults)
    if hasDrawing then
        local obj = Drawing.new(class)
        for k, v in pairs(defaults or {}) do obj[k] = v end
        registry[#registry + 1] = obj
        return obj
    else
        local f = fallback(class, defaults or {})
        registry[#registry + 1] = f
        return f
    end
end

function M.RemoveAll()
    for _, obj in pairs(registry) do
        pcall(function()
            if obj.Remove then obj:Remove() end
        end)
    end
    table.clear(registry)
end

return M

end

_modules['src/utils/env.lua'] = function()
--[[
    Executor environment probe.

    Roblox executors implement the Unified Naming Convention (UNC) — and
    its 2025 successor sUNC — to varying degrees. This module checks
    which UNC functions are available in the current executor so the
    hub can degrade gracefully instead of erroring on a missing global.

    Usage:
        local Env = fetch("src/utils/env.lua")
        if Env.Has("hookmetamethod") then
            -- safe to install silent-aim
        end
        Env.Print()  -- prints a full conformance report to console

    Categories follow the UNC spec
    (github.com/unified-naming-convention/NamingStandard).
]]

local M = {}

local FEATURES = {
    Cache       = {"cache.invalidate", "cache.iscached", "cache.replace", "cloneref", "compareinstances"},
    Closure     = {"checkcaller", "clonefunction", "getcallingscript", "getscriptclosure",
                   "hookfunction", "iscclosure", "islclosure", "isexecutorclosure", "loadstring",
                   "newcclosure"},
    Console     = {"rconsoleclear", "rconsoleinput", "rconsoleprint", "rconsolesettitle"},
    Crypt       = {"crypt.base64encode", "crypt.base64decode", "crypt.encrypt", "crypt.decrypt",
                   "crypt.generatebytes", "crypt.generatekey", "crypt.hash"},
    Debug       = {"debug.getconstant", "debug.getconstants", "debug.getinfo", "debug.getproto",
                   "debug.getprotos", "debug.getstack", "debug.getupvalue", "debug.getupvalues",
                   "debug.setconstant", "debug.setstack", "debug.setupvalue"},
    Drawing     = {"Drawing", "Drawing.new", "Drawing.Fonts", "isrenderobj", "getrenderproperty",
                   "setrenderproperty", "cleardrawcache"},
    Filesystem  = {"readfile", "listfiles", "writefile", "makefolder", "appendfile",
                   "isfile", "isfolder", "delfolder", "delfile", "loadfile", "dofile"},
    Input       = {"isrbxactive", "mouse1click", "mouse1press", "mouse1release",
                   "mouse2click", "mouse2press", "mouse2release", "mousemoveabs", "mousemoverel",
                   "mousescroll", "keypress", "keyrelease"},
    Instances   = {"fireclickdetector", "fireproximityprompt", "firesignal", "firetouchinterest",
                   "getcallbackvalue", "getconnections", "getcustomasset", "gethiddenproperty",
                   "gethui", "getinstances", "getnilinstances", "isscriptable", "sethiddenproperty",
                   "setrbxclipboard", "setscriptable"},
    Metatable   = {"getrawmetatable", "hookmetamethod", "getnamecallmethod", "isreadonly",
                   "setrawmetatable", "setreadonly"},
    Misc        = {"identifyexecutor", "lz4compress", "lz4decompress", "messagebox", "queue_on_teleport",
                   "request", "setclipboard", "setfflag", "getfflag", "setfpscap"},
    Scripts     = {"getgc", "getgenv", "getloadedmodules", "getrenv", "getrunningscripts",
                   "getscriptbytecode", "getscripthash", "getscripts", "getsenv", "getthreadidentity",
                   "setthreadidentity"},
    WebSocket   = {"WebSocket", "WebSocket.connect"},
}

local function tryResolve(name)
    -- Direct global lookup
    local ok, v = pcall(function()
        local cur = getfenv(0)
        for part in name:gmatch("[^.]+") do
            cur = cur[part]
            if cur == nil then return nil end
        end
        return cur
    end)
    if ok and v ~= nil then return v end
    -- _G lookup
    ok, v = pcall(function()
        local cur = _G
        for part in name:gmatch("[^.]+") do
            cur = cur[part]
            if cur == nil then return nil end
        end
        return cur
    end)
    if ok then return v end
    return nil
end

M.Probe = {}
M.Categories = {}
M.Conformance = 0
M.Total = 0

local function probe()
    local found, total = 0, 0
    for category, names in pairs(FEATURES) do
        local catFound, catTotal = 0, #names
        for _, n in ipairs(names) do
            total = total + 1
            local v = tryResolve(n)
            local present = v ~= nil
            M.Probe[n] = present
            if present then
                found = found + 1
                catFound = catFound + 1
            end
        end
        M.Categories[category] = {found = catFound, total = catTotal}
    end
    M.Conformance = found / math.max(total, 1)
    M.Total = total
end

probe()

function M.Has(name)
    local v = M.Probe[name]
    if v ~= nil then return v end
    -- runtime lookup for things not in our manifest
    return tryResolve(name) ~= nil
end

function M.Name()
    if M.Has("identifyexecutor") then
        local ok, name, ver = pcall(identifyexecutor)
        if ok and name then return name, ver end
    end
    -- common executor-specific globals
    if syn then return "Synapse X" end
    if KRNL_LOADED or krnl then return "Krnl" end
    if fluxus then return "Fluxus" end
    if Krnl then return "Krnl" end
    if Wave then return "Wave" end
    if AWP then return "AWP" end
    return "Unknown executor"
end

function M.Summary()
    local lines = {}
    table.insert(lines, ("ROGBLOX env probe -- conformance %.1f%% (%d / %d UNC functions)")
        :format(M.Conformance * 100, M.Conformance * M.Total, M.Total))
    table.insert(lines, "executor: " .. tostring(M.Name()))
    for cat, c in pairs(M.Categories) do
        table.insert(lines, string.format("  %s: %d / %d", cat, c.found, c.total))
    end
    return table.concat(lines, "\n")
end

function M.Print()
    print(M.Summary())
end

-- short, named helpers that the rest of the hub will use
M.CanHookMeta     = M.Has("hookmetamethod") and M.Has("getrawmetatable") and M.Has("getnamecallmethod")
M.CanHookFn       = M.Has("hookfunction")
M.CanFileSystem   = M.Has("readfile") and M.Has("writefile") and M.Has("isfile")
M.CanDrawing      = M.Has("Drawing")
M.CanRequest      = M.Has("request") or M.Has("syn.request") or M.Has("http.request")
M.CanCheckCaller  = M.Has("checkcaller")
M.CanNewCClosure  = M.Has("newcclosure")
M.CanFFlag        = M.Has("setfflag") and M.Has("getfflag")
M.CanWebSocket    = M.Has("WebSocket")
M.CanLZ4          = M.Has("lz4compress") and M.Has("lz4decompress")

return M

end

_modules['src/modules/aimbot.lua'] = function()
--[[
    Aimbot — professional implementation.

    Target selection modes:
        Crosshair      — closest screen distance to viewport center
        Mouse          — closest screen distance to current mouse position
        Distance       — closest in 3D space to local player
        LowestHP       — lowest current health (within FOV)

    Per-part priority list — first part found on target wins.
    Prediction — leads the target using its assembly velocity.
    Visibility — Workspace:Raycast verifies line of sight.
    Smoothing — Linear / Sine / Exponential interpolation curve.
    Auto-switch — abandons target when dead / out of FOV / lost LOS.
    Friend list — comma-separated names that are never targeted.
    Trigger bot — fires when crosshair is on a player and gates by delay.

    Publishes M.LockedTarget for the HUD module to render the panel.
]]

local Players          = game:GetService("Players")
local RunService       = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace        = game:GetService("Workspace")

local M = {}

local state = {
    Enabled        = false,
    Held           = false,
    HoldMode       = true,
    HoldButton     = Enum.UserInputType.MouseButton2,
    Mode           = "Crosshair",           -- Crosshair | Mouse | Distance | LowestHP
    Parts          = {"Head", "HumanoidRootPart", "UpperTorso"},
    FOV            = 120,
    MaxDistance    = 1000,
    CheckTeam      = false,
    CheckLOS       = true,
    AutoSwitch     = true,
    SmoothCurve    = "Sine",                -- Linear | Sine | Exponential
    Smoothness     = 0.35,
    Prediction     = 0.16,                  -- seconds of lead
    SnapLine       = false,
    ShowFOV        = true,
    FOVColor       = Color3.fromRGB(140, 100, 255),
    FOVFilled      = false,
    Sticky         = true,                  -- stays on a target until lost
    FriendList     = {},                    -- [name] = true
    TriggerBot     = false,
    TriggerDelay   = 0.05,
    TriggerWindow  = 6,                     -- pixels from center
}

M.LockedTarget = nil
local conns = {}
local fov, fovOutline, snapLine

-- ---------- Helpers ----------

local function getLocalChar()
    local lp = Players.LocalPlayer
    return lp and lp.Character
end

local function isAlive(plr)
    local c = plr and plr.Character
    local hum = c and c:FindFirstChildOfClass("Humanoid")
    return hum and hum.Health > 0
end

local function sameTeam(plr)
    local lp = Players.LocalPlayer
    if not (lp and lp.Team and plr.Team) then return false end
    return lp.Team == plr.Team
end

local function isFriend(plr)
    return state.FriendList[plr.Name] or state.FriendList[plr.DisplayName]
end

local function getTargetPart(plr)
    local char = plr.Character
    if not char then return nil end
    for _, name in ipairs(state.Parts) do
        local p = char:FindFirstChild(name)
        if p then return p end
    end
    return char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
end

local function hasLOS(target)
    local cam = Workspace.CurrentCamera
    if not (cam and target) then return false end
    local origin = cam.CFrame.Position
    local dir = (target.Position - origin)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local ignore = {getLocalChar()}
    if cam then table.insert(ignore, cam) end
    params.FilterDescendantsInstances = ignore
    local result = Workspace:Raycast(origin, dir, params)
    if not result then return true end
    return result.Instance:IsDescendantOf(target.Parent)
end

local function predict(part)
    if state.Prediction <= 0 then return part.Position end
    local vel = part.AssemblyLinearVelocity
    return part.Position + vel * state.Prediction
end

local function screenOf(point)
    local cam = Workspace.CurrentCamera
    local p, on = cam:WorldToViewportPoint(point)
    return Vector2.new(p.X, p.Y), on, p.Z
end

local function viewportCenter()
    local cam = Workspace.CurrentCamera
    local v = cam.ViewportSize
    return Vector2.new(v.X / 2, v.Y / 2)
end

local function mousePos()
    return UserInputService:GetMouseLocation()
end

local function curveAlpha(rawAlpha)
    local a = math.clamp(1 - state.Smoothness, 0.01, 1)
    rawAlpha = math.clamp(rawAlpha, 0, 1) * a
    if state.SmoothCurve == "Sine" then
        return math.sin(rawAlpha * math.pi / 2)
    elseif state.SmoothCurve == "Exponential" then
        return 1 - math.exp(-5 * rawAlpha)
    end
    return rawAlpha
end

-- ---------- Target selection ----------

local function findTarget()
    local cam = Workspace.CurrentCamera
    if not cam then return nil end
    local me = getLocalChar()
    local myRoot = me and me:FindFirstChild("HumanoidRootPart")
    if not myRoot then return nil end

    local origin
    if state.Mode == "Crosshair" then origin = viewportCenter()
    elseif state.Mode == "Mouse" then origin = mousePos()
    end

    local bestTarget, bestScore
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer and isAlive(plr)
        and not (state.CheckTeam and sameTeam(plr))
        and not isFriend(plr) then
            local part = getTargetPart(plr)
            if part then
                local screenP, onScreen = screenOf(part.Position)
                local distance = (part.Position - myRoot.Position).Magnitude
                if distance <= state.MaxDistance and (onScreen or state.Mode == "Distance") then
                    local score
                    if state.Mode == "Distance" then
                        score = distance
                    elseif state.Mode == "LowestHP" then
                        local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                        local screenDist = onScreen and (screenP - viewportCenter()).Magnitude or math.huge
                        if screenDist <= state.FOV then
                            score = hum and hum.Health or math.huge
                        end
                    else
                        local screenDist = (screenP - origin).Magnitude
                        if screenDist <= state.FOV then score = screenDist end
                    end
                    if score and (not bestScore or score < bestScore) then
                        if not state.CheckLOS or hasLOS(part) then
                            bestTarget = plr
                            bestScore = score
                        end
                    end
                end
            end
        end
    end
    return bestTarget
end

-- ---------- Target tracking ----------

local function isTargetStillValid(plr)
    if not (plr and isAlive(plr)) then return false end
    if state.CheckTeam and sameTeam(plr) then return false end
    if isFriend(plr) then return false end
    local part = getTargetPart(plr)
    if not part then return false end
    if state.CheckLOS and not hasLOS(part) then return false end
    local screenP, onScreen = screenOf(part.Position)
    if not onScreen then return false end
    if state.Mode == "Crosshair" then
        local d = (screenP - viewportCenter()).Magnitude
        if d > state.FOV then return false end
    elseif state.Mode == "Mouse" then
        local d = (screenP - mousePos()).Magnitude
        if d > state.FOV then return false end
    end
    return true
end

-- ---------- Drawing setup ----------

local function buildFOV()
    if not (Drawing and Drawing.new) then return end
    if fov then return end
    fovOutline = Drawing.new("Circle")
    fovOutline.Thickness = 3
    fovOutline.Color = Color3.new(0, 0, 0)
    fovOutline.Transparency = 0.5
    fovOutline.NumSides = 80
    fovOutline.Filled = false
    fovOutline.Visible = false

    fov = Drawing.new("Circle")
    fov.Thickness = 1
    fov.Color = state.FOVColor
    fov.NumSides = 80
    fov.Filled = false
    fov.Visible = false

    snapLine = Drawing.new("Line")
    snapLine.Color = state.FOVColor
    snapLine.Thickness = 1
    snapLine.Visible = false
end

local function updateFOV()
    if not fov then return end
    local center = viewportCenter()
    fov.Position = center
    fov.Radius = state.FOV
    fov.Color = state.FOVColor
    fov.Filled = state.FOVFilled
    fov.Transparency = state.FOVFilled and 0.2 or 1
    fov.Visible = state.ShowFOV and (state.Enabled or (state.HoldMode and state.Held))
    fovOutline.Position = center
    fovOutline.Radius = state.FOV
    fovOutline.Visible = fov.Visible and not state.FOVFilled
end

local function clearFOV()
    for _, obj in ipairs({fov, fovOutline, snapLine}) do
        if obj then pcall(function() obj:Remove() end) end
    end
    fov, fovOutline, snapLine = nil, nil, nil
end

-- ---------- Aim step ----------

local function aimStep()
    if not state.Enabled then M.LockedTarget = nil; return end
    if state.HoldMode and not state.Held then M.LockedTarget = nil; return end

    local target = M.LockedTarget
    if state.Sticky and target and isTargetStillValid(target) then
        -- stay on it
    else
        target = findTarget()
    end
    M.LockedTarget = target

    if not target then
        if snapLine then snapLine.Visible = false end
        return
    end

    local part = getTargetPart(target)
    if not part then return end
    local cam = Workspace.CurrentCamera
    if not cam then return end

    local aimPos = predict(part)
    local goal = CFrame.new(cam.CFrame.Position, aimPos)
    local alpha = curveAlpha(1)
    if alpha >= 0.999 then
        cam.CFrame = goal
    else
        cam.CFrame = cam.CFrame:Lerp(goal, alpha)
    end

    if state.SnapLine and snapLine then
        local screenP = screenOf(aimPos)
        snapLine.From = viewportCenter()
        snapLine.To = screenP
        snapLine.Color = state.FOVColor
        snapLine.Visible = true
    elseif snapLine then
        snapLine.Visible = false
    end
end

-- ---------- Trigger bot ----------

local triggerCooldown = 0
local function triggerStep()
    if not state.TriggerBot then return end
    if tick() < triggerCooldown then return end
    local cam = Workspace.CurrentCamera
    if not cam then return end
    local center = viewportCenter()
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer and isAlive(plr)
        and not (state.CheckTeam and sameTeam(plr))
        and not isFriend(plr) then
            local part = getTargetPart(plr)
            if part then
                local screenP, onScreen = screenOf(part.Position)
                if onScreen and (screenP - center).Magnitude <= state.TriggerWindow then
                    if not state.CheckLOS or hasLOS(part) then
                        pcall(function()
                            if mouse1press and mouse1release then
                                mouse1press(); task.wait(state.TriggerDelay); mouse1release()
                            elseif mouse1click then mouse1click() end
                        end)
                        triggerCooldown = tick() + 0.15
                        return
                    end
                end
            end
        end
    end
end

-- ---------- Build UI ----------

function M.Build(tab, ctx)
    buildFOV()

    local main = tab:AddSection("Aimbot")
    main:AddToggle("Enabled", false, function(v) state.Enabled = v end)
    main:AddToggle("Hold to aim", true, function(v) state.HoldMode = v end)
    main:AddDropdown("Hold button", {"MouseButton2","MouseButton1","E","Q"}, "MouseButton2", function(v)
        if v == "MouseButton1" then state.HoldButton = Enum.UserInputType.MouseButton1
        elseif v == "MouseButton2" then state.HoldButton = Enum.UserInputType.MouseButton2
        elseif v == "E" then state.HoldButton = Enum.KeyCode.E
        elseif v == "Q" then state.HoldButton = Enum.KeyCode.Q end
    end)
    main:AddDropdown("Target mode", {"Crosshair","Mouse","Distance","LowestHP"}, "Crosshair", function(v) state.Mode = v end)
    main:AddDropdown("Target parts", {"Head","Neck","UpperTorso","Torso","HumanoidRootPart","LowerTorso"},
                     {"Head","HumanoidRootPart","UpperTorso"}, function(v)
        local list = {}
        for k, on in pairs(v) do if on then table.insert(list, k) end end
        if #list > 0 then state.Parts = list end
    end, {Multi = true})
    main:AddSlider("FOV (radius)", 10, 800, 120, function(v) state.FOV = v end)
    main:AddSlider("Max distance (m)", 50, 5000, 1000, function(v) state.MaxDistance = v end)
    main:AddDivider()

    local aim = tab:AddSection("Smoothing & Prediction")
    aim:AddDropdown("Smoothing curve", {"Linear","Sine","Exponential"}, "Sine", function(v) state.SmoothCurve = v end)
    aim:AddSlider("Smoothness", 0, 0.95, 0.35, function(v) state.Smoothness = v end, {Decimals = 2})
    aim:AddSlider("Prediction (s)", 0, 0.6, 0.16, function(v) state.Prediction = v end, {Decimals = 2})
    aim:AddToggle("Sticky lock", true, function(v) state.Sticky = v end)
    aim:AddToggle("Auto-switch on lost", true, function(v) state.AutoSwitch = v end)

    local checks = tab:AddSection("Filters")
    checks:AddToggle("Team check", false, function(v) state.CheckTeam = v end)
    checks:AddToggle("Wall check (LOS)", true, function(v) state.CheckLOS = v end)
    checks:AddTextBox("Friend list (comma-sep)", "Alice, Bob", function(v)
        state.FriendList = {}
        for name in string.gmatch(v, "[^,]+") do
            local trimmed = name:match("^%s*(.-)%s*$")
            if trimmed ~= "" then state.FriendList[trimmed] = true end
        end
    end)

    local visuals = tab:AddSection("Visuals")
    visuals:AddToggle("Show FOV circle", true, function(v) state.ShowFOV = v end)
    visuals:AddToggle("FOV filled", false, function(v) state.FOVFilled = v end)
    visuals:AddColorPicker("FOV color", Color3.fromRGB(140,100,255), function(v) state.FOVColor = v end)
    visuals:AddToggle("Snap line to target", false, function(v) state.SnapLine = v end)

    local trig = tab:AddSection("Trigger Bot")
    trig:AddToggle("Enabled", false, function(v) state.TriggerBot = v end)
    trig:AddSlider("Window (px)", 1, 50, 6, function(v) state.TriggerWindow = v end)
    trig:AddSlider("Press delay (ms)", 0, 500, 50, function(v) state.TriggerDelay = v / 1000 end)

    -- input
    conns.inputDown = UserInputService.InputBegan:Connect(function(input, processed)
        if input.UserInputType == state.HoldButton or input.KeyCode == state.HoldButton then
            state.Held = true
        end
    end)
    conns.inputUp = UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == state.HoldButton or input.KeyCode == state.HoldButton then
            state.Held = false
        end
    end)

    -- main render loop
    conns.render = RunService.RenderStepped:Connect(function()
        updateFOV()
        aimStep()
        triggerStep()
    end)
end

function M.Unload()
    for _, c in pairs(conns) do pcall(function() c:Disconnect() end) end
    conns = {}
    clearFOV()
    state.Enabled = false
    M.LockedTarget = nil
end

M.State = state
return M

end

_modules['src/modules/esp.lua'] = function()
--[[
    ESP v2 — pro implementation.

    - Drawing object POOL: pre-allocate slots, reuse on player join,
      never tear down during a match. Major perf win over per-player
      Instance.new() recreation.
    - Skeleton ESP for both R6 and R15 rigs (canonical bone tables).
    - Box / corner / outline modes
    - Name, distance, weapon (currently equipped Tool) labels
    - Health bar with distance-fade and color gradient (red->green)
    - Tracer with 4 origin modes + distance color gradient
    - Highlight chams with DepthMode=AlwaysOnTop and distance fade
    - Team check + team color + max distance + per-update throttle
]]

local Players       = game:GetService("Players")
local RunService    = game:GetService("RunService")
local Workspace     = game:GetService("Workspace")
local UserInputService = game:GetService("UserInputService")

local M = {}

local state = {
    Enabled       = false,
    Box           = true,
    BoxStyle      = "Outline",      -- Outline | Corner | Filled
    Name          = true,
    Distance      = true,
    Health        = true,
    Weapon        = false,
    Tracer        = false,
    Chams         = false,
    Skeleton      = false,
    TeamCheck     = false,
    TeamColor     = false,
    Color         = Color3.fromRGB(140, 100, 255),
    EnemyColor    = Color3.fromRGB(235,  90, 100),
    AllyColor     = Color3.fromRGB(120, 220, 140),
    MaxDist       = 1000,
    DistFade      = true,
    TracerFrom    = "Bottom",       -- Bottom | Center | Top | Mouse
    ChamsTransp   = 0.5,
}

-- Canonical bone tables (from KaenDeveloper / Stefanuk12 / DevForum consensus)
local SKELETON_R15 = {
    {"Head", "UpperTorso"}, {"UpperTorso", "LowerTorso"},
    {"UpperTorso", "LeftUpperArm"},  {"LeftUpperArm", "LeftLowerArm"},  {"LeftLowerArm", "LeftHand"},
    {"UpperTorso", "RightUpperArm"}, {"RightUpperArm", "RightLowerArm"}, {"RightLowerArm", "RightHand"},
    {"LowerTorso", "LeftUpperLeg"},  {"LeftUpperLeg", "LeftLowerLeg"},  {"LeftLowerLeg", "LeftFoot"},
    {"LowerTorso", "RightUpperLeg"}, {"RightUpperLeg", "RightLowerLeg"},{"RightLowerLeg", "RightFoot"},
}
local SKELETON_R6 = {
    {"Head", "Torso"},
    {"Torso", "Left Arm"}, {"Torso", "Right Arm"},
    {"Torso", "Left Leg"}, {"Torso", "Right Leg"},
}
-- 14 R15 bones + 5 R6, but each player only renders one rig, so 14 lines
-- per slot is the upper bound.
local SKELETON_LINES_PER_PLAYER = 14

-- ============================================================
-- Drawing pool
-- ============================================================

local HAS_DRAWING = type(Drawing) == "table" and type(Drawing.new) == "function"

local function newDrawing(class, props)
    if not HAS_DRAWING then return nil end
    local obj = Drawing.new(class)
    for k, v in pairs(props or {}) do obj[k] = v end
    return obj
end

-- One pool slot per player slot. Pre-allocated for MAX_SLOTS players;
-- reused across joins/leaves. Lines for skeleton are part of the slot.
local MAX_SLOTS = 60   -- big enough for any realistic server
local pool = {}        -- index -> {box, boxOutline, name, dist, weapon, hpBg, hpFill, tracer, skeleton={lines}}
local slotByPlayer = {} -- [player] = slot index
local slotInUse = {}   -- [index] = bool

local function buildSlot()
    local slot = {}
    slot.boxOutline = newDrawing("Square", {Thickness = 3, Filled = false,
        Color = Color3.new(0,0,0), Transparency = 0.5, Visible = false})
    slot.box = newDrawing("Square", {Thickness = 1, Filled = false,
        Color = state.Color, Visible = false})
    slot.boxFill = newDrawing("Square", {Thickness = 1, Filled = true,
        Color = state.Color, Transparency = 0.2, Visible = false})
    slot.name = newDrawing("Text", {Size = 13, Center = true, Outline = true,
        Color = state.Color, Font = 2, Visible = false})
    slot.dist = newDrawing("Text", {Size = 11, Center = true, Outline = true,
        Color = Color3.new(1,1,1), Font = 2, Visible = false})
    slot.weapon = newDrawing("Text", {Size = 11, Center = true, Outline = true,
        Color = Color3.fromRGB(255,200,100), Font = 2, Visible = false})
    slot.hpBg = newDrawing("Square", {Thickness = 1, Filled = true,
        Color = Color3.fromRGB(20,20,20), Visible = false})
    slot.hpFill = newDrawing("Square", {Thickness = 1, Filled = true,
        Color = Color3.fromRGB(90,200,120), Visible = false})
    slot.tracer = newDrawing("Line", {Thickness = 1, Color = state.Color, Visible = false})
    slot.skeleton = {}
    for i = 1, SKELETON_LINES_PER_PLAYER do
        slot.skeleton[i] = newDrawing("Line", {Thickness = 1, Color = state.Color, Visible = false})
    end
    -- Highlight chams (Instance-based, not Drawing)
    local hl = Instance.new("Highlight")
    hl.Name = "ROGBLOX_Chams"
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    hl.FillTransparency = state.ChamsTransp
    hl.OutlineTransparency = 0
    hl.FillColor = state.Color
    hl.OutlineColor = state.Color
    hl.Enabled = false
    slot.chams = hl
    return slot
end

local function ensurePool()
    if #pool > 0 then return end
    for i = 1, MAX_SLOTS do
        pool[i] = buildSlot()
        slotInUse[i] = false
    end
end

local function acquireSlot(plr)
    if slotByPlayer[plr] then return slotByPlayer[plr] end
    for i = 1, MAX_SLOTS do
        if not slotInUse[i] then
            slotInUse[i] = true
            slotByPlayer[plr] = i
            return i
        end
    end
    return nil  -- pool exhausted, skip
end

local function hideSlot(slot)
    if not slot then return end
    slot.box.Visible = false
    slot.boxOutline.Visible = false
    if slot.boxFill then slot.boxFill.Visible = false end
    slot.name.Visible = false
    slot.dist.Visible = false
    slot.weapon.Visible = false
    slot.hpBg.Visible = false
    slot.hpFill.Visible = false
    slot.tracer.Visible = false
    for _, ln in ipairs(slot.skeleton) do ln.Visible = false end
    slot.chams.Enabled = false
end

local function releaseSlot(plr)
    local idx = slotByPlayer[plr]
    if not idx then return end
    hideSlot(pool[idx])
    slotInUse[idx] = false
    slotByPlayer[plr] = nil
end

local function destroyPool()
    for _, slot in ipairs(pool) do
        for _, obj in pairs(slot) do
            if type(obj) == "table" then
                for _, ln in ipairs(obj) do
                    if ln and ln.Remove then pcall(function() ln:Remove() end) end
                end
            elseif typeof(obj) == "Instance" then
                obj:Destroy()
            elseif obj and obj.Remove then
                pcall(function() obj:Remove() end)
            end
        end
    end
    pool = {}
    slotByPlayer = {}
    slotInUse = {}
end

-- ============================================================
-- Color helpers
-- ============================================================

local function colorFor(plr)
    if state.TeamColor and plr.Team and plr.TeamColor then
        return plr.TeamColor.Color
    end
    local lp = Players.LocalPlayer
    if lp and lp.Team and plr.Team and lp.Team == plr.Team then
        return state.AllyColor
    end
    return state.EnemyColor
end

local function fadeColor(c, dist)
    if not state.DistFade then return c, 0 end
    local t = math.clamp(dist / state.MaxDist, 0, 1)
    local transp = t * 0.6   -- 0.0 close, 0.6 far
    return c, transp
end

local function hpColor(pct)
    if pct > 0.5 then
        return Color3.fromRGB(math.floor(255 * 2 * (1 - pct)), 200, 80)
    else
        return Color3.fromRGB(255, math.floor(200 * 2 * pct), 80)
    end
end

local function getEquippedWeapon(plr)
    local char = plr.Character
    if not char then return nil end
    for _, t in ipairs(char:GetChildren()) do
        if t:IsA("Tool") then return t.Name end
    end
    return nil
end

local function tracerOrigin()
    local cam = Workspace.CurrentCamera
    local v = cam.ViewportSize
    if state.TracerFrom == "Top"    then return Vector2.new(v.X/2, 0)
    elseif state.TracerFrom == "Center" then return Vector2.new(v.X/2, v.Y/2)
    elseif state.TracerFrom == "Mouse"  then return UserInputService:GetMouseLocation()
    end
    return Vector2.new(v.X/2, v.Y)
end

-- ============================================================
-- Per-player update
-- ============================================================

local function updateSlot(plr)
    local idx = slotByPlayer[plr]
    if not idx then return end
    local slot = pool[idx]
    if not slot then return end

    local lp = Players.LocalPlayer
    local char = plr.Character
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    local head = char and char:FindFirstChild("Head")

    local visible = state.Enabled and char and hum and hrp and head and hum.Health > 0
    if state.TeamCheck and lp and lp.Team and plr.Team and lp.Team == plr.Team then
        visible = false
    end

    if not visible then hideSlot(slot); return end

    local cam = Workspace.CurrentCamera
    local distance = (cam.CFrame.Position - hrp.Position).Magnitude
    if distance > state.MaxDist then hideSlot(slot); return end

    local rootScreen, onScreen = cam:WorldToViewportPoint(hrp.Position)
    if not onScreen then hideSlot(slot); return end

    local headScreen = cam:WorldToViewportPoint(head.Position + Vector3.new(0, 0.5, 0))
    local footPos = hrp.Position - Vector3.new(0, 3, 0)
    local footScreen = cam:WorldToViewportPoint(footPos)
    local height = math.abs(footScreen.Y - headScreen.Y)
    local width  = height * 0.55
    local boxX, boxY = rootScreen.X - width/2, headScreen.Y

    local baseColor = colorFor(plr)
    local color, transp = fadeColor(baseColor, distance)

    -- ----- Box -----
    if state.Box then
        if state.BoxStyle == "Filled" and slot.boxFill then
            slot.boxFill.Position = Vector2.new(boxX, boxY)
            slot.boxFill.Size = Vector2.new(width, height)
            slot.boxFill.Color = color
            slot.boxFill.Transparency = 0.7
            slot.boxFill.Visible = true
            slot.box.Visible = false
            slot.boxOutline.Visible = false
        else
            slot.box.Position = Vector2.new(boxX, boxY)
            slot.box.Size = Vector2.new(width, height)
            slot.box.Color = color
            slot.box.Transparency = 1 - transp
            slot.box.Visible = true
            slot.boxOutline.Position = slot.box.Position
            slot.boxOutline.Size = slot.box.Size
            slot.boxOutline.Visible = true
            if slot.boxFill then slot.boxFill.Visible = false end
        end
    else
        slot.box.Visible = false
        slot.boxOutline.Visible = false
        if slot.boxFill then slot.boxFill.Visible = false end
    end

    -- ----- Name -----
    if state.Name then
        slot.name.Position = Vector2.new(rootScreen.X, boxY - 16)
        slot.name.Text = plr.DisplayName
        slot.name.Color = color
        slot.name.Visible = true
    else slot.name.Visible = false end

    -- ----- Distance -----
    if state.Distance then
        slot.dist.Position = Vector2.new(rootScreen.X, boxY + height + 2)
        slot.dist.Text = string.format("[%dm]", math.floor(distance))
        slot.dist.Visible = true
    else slot.dist.Visible = false end

    -- ----- Weapon -----
    if state.Weapon then
        local wpn = getEquippedWeapon(plr)
        if wpn then
            slot.weapon.Position = Vector2.new(rootScreen.X, boxY - 28)
            slot.weapon.Text = "[" .. wpn .. "]"
            slot.weapon.Visible = true
        else slot.weapon.Visible = false end
    else slot.weapon.Visible = false end

    -- ----- Health bar -----
    if state.Health then
        local pct = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
        slot.hpBg.Position = Vector2.new(boxX - 6, boxY)
        slot.hpBg.Size = Vector2.new(3, height)
        slot.hpBg.Visible = true
        slot.hpFill.Position = Vector2.new(boxX - 6, boxY + (1 - pct) * height)
        slot.hpFill.Size = Vector2.new(3, height * pct)
        slot.hpFill.Color = hpColor(pct)
        slot.hpFill.Visible = true
    else
        slot.hpBg.Visible = false
        slot.hpFill.Visible = false
    end

    -- ----- Tracer -----
    if state.Tracer then
        local origin = tracerOrigin()
        slot.tracer.From = origin
        slot.tracer.To   = Vector2.new(rootScreen.X, boxY + height)
        local distT = math.clamp(distance / 200, 0, 1)
        slot.tracer.Color = Color3.new(distT, 1 - distT, 0)
        slot.tracer.Visible = true
    else slot.tracer.Visible = false end

    -- ----- Skeleton -----
    if state.Skeleton then
        local rig
        if char:FindFirstChild("UpperTorso") then rig = SKELETON_R15
        elseif char:FindFirstChild("Torso") then  rig = SKELETON_R6
        end
        if rig then
            for i, bone in ipairs(rig) do
                local a = char:FindFirstChild(bone[1])
                local b = char:FindFirstChild(bone[2])
                local ln = slot.skeleton[i]
                if a and b and ln then
                    local sa = cam:WorldToViewportPoint(a.Position)
                    local sb = cam:WorldToViewportPoint(b.Position)
                    if sa.Z > 0 and sb.Z > 0 then
                        ln.From = Vector2.new(sa.X, sa.Y)
                        ln.To   = Vector2.new(sb.X, sb.Y)
                        ln.Color = color
                        ln.Visible = true
                    else ln.Visible = false end
                end
            end
            -- hide unused lines beyond rig length
            for i = #rig + 1, #slot.skeleton do
                slot.skeleton[i].Visible = false
            end
        end
    else
        for _, ln in ipairs(slot.skeleton) do ln.Visible = false end
    end

    -- ----- Chams -----
    if state.Chams then
        slot.chams.Adornee = char
        slot.chams.FillColor = color
        slot.chams.OutlineColor = color
        slot.chams.FillTransparency = state.ChamsTransp + transp * 0.3
        slot.chams.Enabled = true
        if not slot.chams.Parent then slot.chams.Parent = char end
    else
        slot.chams.Enabled = false
    end
end

-- ============================================================
-- Build / Unload
-- ============================================================

local conns = {}

local function onPlayerAdded(plr)
    if plr == Players.LocalPlayer then return end
    acquireSlot(plr)
end

local function onPlayerRemoving(plr)
    releaseSlot(plr)
end

function M.Build(tab, ctx)
    ensurePool()
    for _, plr in ipairs(Players:GetPlayers()) do onPlayerAdded(plr) end
    conns.added = Players.PlayerAdded:Connect(onPlayerAdded)
    conns.left  = Players.PlayerRemoving:Connect(onPlayerRemoving)

    local main = tab:AddSection("ESP")
    main:AddToggle("Enabled", false, function(v)
        state.Enabled = v
        if not v then for _, slot in ipairs(pool) do hideSlot(slot) end end
    end)
    main:AddToggle("Box", true, function(v) state.Box = v end)
    main:AddDropdown("Box style", {"Outline","Corner","Filled"}, "Outline", function(v) state.BoxStyle = v end)
    main:AddToggle("Name tag", true, function(v) state.Name = v end)
    main:AddToggle("Distance", true, function(v) state.Distance = v end)
    main:AddToggle("Health bar", true, function(v) state.Health = v end)
    main:AddToggle("Weapon ESP", false, function(v) state.Weapon = v end)
    main:AddToggle("Tracers", false, function(v) state.Tracer = v end)
    main:AddDropdown("Tracer origin", {"Bottom","Center","Top","Mouse"}, "Bottom", function(v) state.TracerFrom = v end)
    main:AddToggle("Skeleton (R6/R15)", false, function(v) state.Skeleton = v end)
    main:AddToggle("Chams (highlight)", false, function(v) state.Chams = v end)
    main:AddSlider("Chams transparency", 0, 1, 0.5, function(v) state.ChamsTransp = v end, {Decimals = 2})
    main:AddSlider("Max distance", 50, 5000, 1000, function(v) state.MaxDist = v end)
    main:AddToggle("Distance fade", true, function(v) state.DistFade = v end)

    local filters = tab:AddSection("Filters & Colors")
    filters:AddToggle("Team check (hide allies)", false, function(v) state.TeamCheck = v end)
    filters:AddToggle("Use team color", false, function(v) state.TeamColor = v end)
    filters:AddColorPicker("Enemy color", state.EnemyColor, function(c) state.EnemyColor = c end)
    filters:AddColorPicker("Ally color",  state.AllyColor,  function(c) state.AllyColor = c end)

    -- main loop
    conns.render = RunService.RenderStepped:Connect(function()
        for plr, _ in pairs(slotByPlayer) do
            updateSlot(plr)
        end
    end)
end

function M.Unload()
    for _, c in pairs(conns) do pcall(function() c:Disconnect() end) end
    conns = {}
    destroyPool()
end

M.State = state
return M

end

_modules['src/modules/combat_extras.lua'] = function()
--[[
    Combat extras — silent aim hook, hitbox expander, kill aura, god-mode attempts,
    no-recoil shim. Many of these are game-specific; defaults use the broadest
    patterns that work on the majority of FPS/shooter Roblox titles.
]]

local Players          = game:GetService("Players")
local RunService       = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace        = game:GetService("Workspace")

local M = {}
local conns = {}
local alive = false   -- gate for background loops
local hookState = {}  -- snapshot of metatable handlers we replaced

local state = {
    SilentAim        = false,
    SilentFOV        = 50,
    SilentTeamCheck  = false,
    HitboxExpand     = false,
    HitboxSize       = 12,
    HitboxTransparency = 0.7,
    KillAura         = false,
    KillAuraRange    = 12,
    KillAuraRate     = 0.1,
    GodMode          = false,
    AntiAim          = false,
}

local function getRoot()
    local lp = Players.LocalPlayer
    local c = lp and lp.Character
    return c and c:FindFirstChild("HumanoidRootPart")
end

local function getHum()
    local lp = Players.LocalPlayer
    local c = lp and lp.Character
    return c and c:FindFirstChildOfClass("Humanoid")
end

-- ---------- Silent Aim ----------
-- Hooks the most common targeting methods game scripts use:
-- mouse.Hit, mouse.Target, GetMouseLocation, raycasts.

local hookedSilent = false
local origMouseHit, origMouseTarget

local function closestToCenter()
    local cam = Workspace.CurrentCamera
    if not cam then return nil end
    local center = cam.ViewportSize / 2
    local best, bestDist
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer then
            local char = plr.Character
            local head = char and char:FindFirstChild("Head")
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if head and hum and hum.Health > 0 then
                if not (state.SilentTeamCheck and plr.Team and Players.LocalPlayer.Team == plr.Team) then
                    local p, on = cam:WorldToViewportPoint(head.Position)
                    if on then
                        local d = (Vector2.new(p.X, p.Y) - center).Magnitude
                        if d <= state.SilentFOV and (not bestDist or d < bestDist) then
                            best, bestDist = plr, d
                        end
                    end
                end
            end
        end
    end
    return best
end

local function hookSilentAim()
    if hookedSilent then return end
    if not (hookmetamethod and getrawmetatable) then return end
    hookedSilent = true

    local mt = getrawmetatable(game)
    local oldIndex = mt.__index
    local oldNamecall = mt.__namecall
    if setreadonly then setreadonly(mt, false) end

    -- Save originals so Unload can restore. The metatable can't truly be
    -- "unhooked" via hookmetamethod, but we can restore the slots we
    -- replaced so subsequent reloads don't chain hooks.
    hookState.mt          = mt
    hookState.oldIndex    = oldIndex
    hookState.oldNamecall = oldNamecall

    local function redirectHead()
        if not state.SilentAim then return nil end
        local target = closestToCenter()
        if not target then return nil end
        local char = target.Character
        return char and char:FindFirstChild("Head")
    end

    -- Guard: if the call originates from our own hub (not from game
    -- code), pass through unmodified so we don't accidentally redirect
    -- our own raycasts/Mouse reads. UNC `checkcaller()` returns true
    -- for executor-side calls.
    local function ourCall()
        if type(checkcaller) ~= "function" then return false end
        local ok, val = pcall(checkcaller)
        return ok and val or false
    end

    mt.__index = newcclosure(function(self, key)
        if state.SilentAim and not ourCall() and typeof(self) == "Instance" and self:IsA("Mouse") then
            local head = redirectHead()
            if head then
                local cam = Workspace.CurrentCamera
                if key == "Hit" then
                    return CFrame.new(head.Position)
                elseif key == "Target" then
                    return head
                elseif key == "X" then
                    if cam then
                        local p = cam:WorldToViewportPoint(head.Position)
                        return math.floor(p.X)
                    end
                elseif key == "Y" then
                    if cam then
                        local p = cam:WorldToViewportPoint(head.Position)
                        return math.floor(p.Y)
                    end
                elseif key == "UnitRay" then
                    if cam then
                        return Ray.new(cam.CFrame.Position,
                                       (head.Position - cam.CFrame.Position).Unit)
                    end
                end
            end
        end
        return oldIndex(self, key)
    end)

    mt.__namecall = newcclosure(function(self, ...)
        local method = getnamecallmethod()
        if state.SilentAim and not ourCall() then
            -- UserInputService:GetMouseLocation()
            if method == "GetMouseLocation"
               and typeof(self) == "Instance"
               and self.ClassName == "UserInputService" then
                local head = redirectHead()
                if head then
                    local cam = Workspace.CurrentCamera
                    if cam then
                        local screen = cam:WorldToViewportPoint(head.Position)
                        return Vector2.new(screen.X, screen.Y)
                    end
                end
            end
            -- Workspace raycast family: Raycast, FindPartOnRay,
            -- FindPartOnRayWithIgnoreList, FindPartOnRayWithWhitelist
            if (method == "Raycast" or method == "FindPartOnRay"
                or method == "FindPartOnRayWithIgnoreList"
                or method == "FindPartOnRayWithWhitelist")
               and typeof(self) == "Instance"
               and self.ClassName == "Workspace" then
                local args = {...}
                local origin = args[1]
                local head = redirectHead()
                -- Type validation: only rewrite when the first arg is
                -- the spatial origin we expect. Avoids breaking unusual
                -- raycast call shapes from custom game scripts.
                if head and typeof(origin) == "Vector3" then
                    args[2] = (head.Position - origin)
                    return oldNamecall(self, table.unpack(args))
                end
            end
        end
        return oldNamecall(self, ...)
    end)
end

-- ---------- Hitbox Expander ----------

local hitboxConn
local function startHitbox()
    if hitboxConn then return end
    hitboxConn = RunService.Heartbeat:Connect(function()
        if not state.HitboxExpand then return end
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= Players.LocalPlayer then
                local char = plr.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp then
                    hrp.Size = Vector3.new(state.HitboxSize, state.HitboxSize, state.HitboxSize)
                    hrp.Transparency = state.HitboxTransparency
                    hrp.Material = Enum.Material.Neon
                    hrp.BrickColor = BrickColor.new("Bright red")
                    hrp.CanCollide = false
                end
            end
        end
    end)
    conns.hitbox = hitboxConn
end

-- ---------- Kill Aura ----------

local function killAuraStep()
    local root = getRoot()
    if not root then return end
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer then
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then
                local d = (hrp.Position - root.Position).Magnitude
                if d <= state.KillAuraRange then
                    -- Try common damage RemoteEvent names. Best-effort.
                    local rs = game:GetService("ReplicatedStorage")
                    for _, candidate in ipairs({"Damage", "DealDamage", "Hit", "Attack"}) do
                        local ev = rs:FindFirstChild(candidate, true)
                        if ev and ev:IsA("RemoteEvent") then
                            pcall(function() ev:FireServer(plr, 1e6) end)
                        end
                    end
                    -- Touch-based: tween a part to the target
                    local touchPart = root.Parent and root.Parent:FindFirstChild("RightHand")
                                   or (root.Parent and root.Parent:FindFirstChild("Right Arm"))
                    if touchPart then
                        local saved = touchPart.CFrame
                        for i = 1, 3 do
                            touchPart.CFrame = hrp.CFrame
                            task.wait()
                        end
                        touchPart.CFrame = saved
                    end
                end
            end
        end
    end
end

-- ---------- God Mode (best-effort) ----------
-- Roblox damage is server-authoritative; client-side godmode is only
-- effective against client-side projectiles or visual damage.

local godConn
local function startGodMode()
    if godConn then return end
    godConn = RunService.Heartbeat:Connect(function()
        if not state.GodMode then return end
        local hum = getHum()
        if hum then
            hum.Health = hum.MaxHealth
        end
    end)
    conns.god = godConn
end

-- ---------- Anti-Aim ----------
-- Spin the root part so the server sees you facing a chaotic direction
-- (only effective in games that use the root's orientation for hitreg).

local antiAimConn
local function startAntiAim()
    if antiAimConn then return end
    antiAimConn = RunService.Heartbeat:Connect(function()
        if not state.AntiAim then return end
        local root = getRoot()
        if root then
            root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, math.random() * math.pi * 2, 0)
        end
    end)
    conns.antiAim = antiAimConn
end

function M.Build(tab, ctx)
    alive = true
    hookSilentAim()
    startHitbox()
    startGodMode()
    startAntiAim()

    local sa = tab:AddSection("Silent Aim")
    sa:AddToggle("Enabled", false, function(v) state.SilentAim = v end)
    sa:AddSlider("FOV", 10, 500, 50, function(v) state.SilentFOV = v end)
    sa:AddToggle("Team check", false, function(v) state.SilentTeamCheck = v end)
    sa:AddLabel("Hooks Mouse.Hit / Mouse.Target / Raycast")

    local hb = tab:AddSection("Hitbox Expander")
    hb:AddToggle("Enabled", false, function(v) state.HitboxExpand = v end)
    hb:AddSlider("Size", 4, 30, 12, function(v) state.HitboxSize = v end)
    hb:AddSlider("Transparency", 0, 1, 0.7, function(v) state.HitboxTransparency = v end)

    local ka = tab:AddSection("Kill Aura (best-effort)")
    ka:AddToggle("Enabled", false, function(v) state.KillAura = v end)
    ka:AddSlider("Range", 4, 40, 12, function(v) state.KillAuraRange = v end)
    ka:AddSlider("Tick rate (ms)", 50, 1000, 100, function(v) state.KillAuraRate = v / 1000 end)
    task.spawn(function()
        while alive do
            task.wait(state.KillAuraRate)
            if state.KillAura then pcall(killAuraStep) end
        end
    end)

    local gm = tab:AddSection("Other")
    gm:AddToggle("God Mode (client-side)", false, function(v) state.GodMode = v end)
    gm:AddToggle("Anti-Aim (root spin)", false, function(v) state.AntiAim = v end)
end

function M.Unload()
    alive = false
    state.SilentAim   = false
    state.HitboxExpand = false
    state.KillAura    = false
    state.GodMode     = false
    state.AntiAim     = false
    -- Restore the metatable slots we hijacked so subsequent reloads
    -- don't chain on top of our handlers.
    if hookedSilent and hookState.mt then
        pcall(function()
            if setreadonly then setreadonly(hookState.mt, false) end
            hookState.mt.__index    = hookState.oldIndex
            hookState.mt.__namecall = hookState.oldNamecall
            if setreadonly then setreadonly(hookState.mt, true) end
        end)
        hookedSilent = false
        hookState = {}
    end
    for _, c in pairs(conns) do
        if c and c.Disconnect then pcall(function() c:Disconnect() end) end
    end
    conns = {}
    hitboxConn, godConn, antiAimConn = nil, nil, nil
end

M.State = state
return M

end

_modules['src/modules/movement.lua'] = function()
--[[
    Movement module — walkspeed, jump, infinite jump, fly, noclip.
]]

local Players          = game:GetService("Players")
local RunService       = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace        = game:GetService("Workspace")

local M = {}
local state = {
    Speed       = 16,
    SpeedEnabled= false,
    Jump        = 50,
    JumpEnabled = false,
    InfJump     = false,
    Fly         = false,
    FlySpeed    = 50,
    Noclip      = false,
    Spinbot     = false,
    SpinSpeed   = 8,
}

local hooks = {}

local function getChar()
    local lp = Players.LocalPlayer
    return lp and lp.Character
end

local function getHum()
    local c = getChar()
    return c and c:FindFirstChildOfClass("Humanoid")
end

local function getRoot()
    local c = getChar()
    return c and c:FindFirstChild("HumanoidRootPart")
end

-- ---------- Speed / Jump ----------

local function applySpeed()
    local hum = getHum()
    if hum then hum.WalkSpeed = state.SpeedEnabled and state.Speed or 16 end
end

local function applyJump()
    local hum = getHum()
    if not hum then return end
    if hum.UseJumpPower then
        hum.JumpPower = state.JumpEnabled and state.Jump or 50
    else
        hum.JumpHeight = state.JumpEnabled and (state.Jump / 4) or 7.2
    end
end

-- ---------- Infinite Jump ----------

local function startInfJump()
    if hooks.infJump then return end
    hooks.infJump = UserInputService.JumpRequest:Connect(function()
        if state.InfJump then
            local hum = getHum()
            if hum then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
        end
    end)
end

-- ---------- Fly ----------

local flyBV, flyBG, flyConn

local function startFly()
    local root = getRoot()
    local hum  = getHum()
    if not root or not hum then return end

    flyBV = Instance.new("BodyVelocity")
    flyBV.MaxForce = Vector3.new(9e9, 9e9, 9e9)
    flyBV.Velocity = Vector3.zero
    flyBV.Parent = root

    flyBG = Instance.new("BodyGyro")
    flyBG.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
    flyBG.P = 1000
    flyBG.D = 50
    flyBG.CFrame = root.CFrame
    flyBG.Parent = root

    flyConn = RunService.RenderStepped:Connect(function()
        if not state.Fly then return end
        local cam = Workspace.CurrentCamera
        if not cam then return end
        local dir = Vector3.zero
        if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.E) or UserInputService:IsKeyDown(Enum.KeyCode.Space) then
            dir = dir + Vector3.new(0, 1, 0)
        end
        if UserInputService:IsKeyDown(Enum.KeyCode.Q) or UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
            dir = dir - Vector3.new(0, 1, 0)
        end
        if dir.Magnitude > 0 then dir = dir.Unit end
        flyBV.Velocity = dir * state.FlySpeed
        flyBG.CFrame = cam.CFrame
    end)
end

local function stopFly()
    if flyConn then flyConn:Disconnect(); flyConn = nil end
    if flyBV then flyBV:Destroy(); flyBV = nil end
    if flyBG then flyBG:Destroy(); flyBG = nil end
end

-- ---------- Noclip ----------

local noclipConn
local function startNoclip()
    if noclipConn then return end
    noclipConn = RunService.Stepped:Connect(function()
        if not state.Noclip then return end
        local char = getChar()
        if not char then return end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") and part.CanCollide then
                part.CanCollide = false
            end
        end
    end)
end
local function stopNoclip() if noclipConn then noclipConn:Disconnect(); noclipConn = nil end end

-- ---------- Spinbot ----------

local spinConn
local function startSpin()
    if spinConn then return end
    spinConn = RunService.Heartbeat:Connect(function(dt)
        if not state.Spinbot then return end
        local root = getRoot()
        if root then
            root.CFrame = root.CFrame * CFrame.Angles(0, math.rad(state.SpinSpeed * 60 * dt), 0)
        end
    end)
end
local function stopSpin() if spinConn then spinConn:Disconnect(); spinConn = nil end end

-- ---------- Re-apply on respawn ----------

local function bindChar()
    local lp = Players.LocalPlayer
    if not lp then return end
    if hooks.charAdded then hooks.charAdded:Disconnect() end
    hooks.charAdded = lp.CharacterAdded:Connect(function(char)
        char:WaitForChild("Humanoid")
        task.wait(0.2)
        applySpeed(); applyJump()
        if state.Fly then stopFly(); startFly() end
    end)
end

function M.Build(tab, ctx)
    bindChar()
    startInfJump()
    startNoclip()
    startSpin()

    local speedSec = tab:AddSection("Speed & Jump")
    speedSec:AddToggle("Walkspeed override", false, function(v) state.SpeedEnabled = v; applySpeed() end)
    speedSec:AddSlider("Walkspeed", 16, 500, 50, function(v) state.Speed = v; applySpeed() end)
    speedSec:AddToggle("Jump override", false, function(v) state.JumpEnabled = v; applyJump() end)
    speedSec:AddSlider("Jump power", 50, 500, 100, function(v) state.Jump = v; applyJump() end)
    speedSec:AddToggle("Infinite jump", false, function(v) state.InfJump = v end)

    local flySec = tab:AddSection("Fly")
    flySec:AddToggle("Enabled", false, function(v)
        state.Fly = v
        if v then startFly() else stopFly() end
    end)
    flySec:AddSlider("Fly speed", 10, 300, 50, function(v) state.FlySpeed = v end)

    local clipSec = tab:AddSection("Clip")
    clipSec:AddToggle("Noclip", false, function(v) state.Noclip = v end)

    local spinSec = tab:AddSection("Spinbot")
    spinSec:AddToggle("Enabled", false, function(v) state.Spinbot = v end)
    spinSec:AddSlider("Spin speed", 1, 60, 8, function(v) state.SpinSpeed = v end)
end

function M.Unload()
    for _, h in pairs(hooks) do
        if h.Disconnect then pcall(function() h:Disconnect() end) end
    end
    hooks = {}
    stopFly(); stopNoclip(); stopSpin()
    state.SpeedEnabled = false; applySpeed()
    state.JumpEnabled = false; applyJump()
end

M.State = state
return M

end

_modules['src/modules/teleport.lua'] = function()
--[[
    Teleport — professional implementation.

    - Live player list (refresh, distance, HP shown next to names)
    - 10 named waypoint slots with save / load / clear / rename
    - TP modes: To, Behind, In front, Above, Below, Aim TP (where camera looks)
    - Pathwalk: smooth interp to destination over N seconds
    - TP history (back / forward stack)
    - Click-TP (Ctrl + click)
    - Server hop, rejoin
]]

local Players          = game:GetService("Players")
local RunService       = game:GetService("RunService")
local TeleportService  = game:GetService("TeleportService")
local UserInputService = game:GetService("UserInputService")
local HttpService      = game:GetService("HttpService")
local Workspace        = game:GetService("Workspace")
local TweenService     = game:GetService("TweenService")

local M = {}

local state = {
    Mode       = "To",      -- To | Behind | InFront | Above | Below | Aim
    Offset     = 3,
    PathWalk   = false,
    PathTime   = 0.5,
    ClickTP    = false,
}

local SLOTS = 10
local saved = {}            -- [slot] = {Name = string, CFrame = CFrame}
local history = {}          -- stack of CFrames before each TP
local future = {}           -- redo stack
local conns = {}

-- ---------- Helpers ----------

local function getChar()
    local lp = Players.LocalPlayer
    return lp and lp.Character
end

local function getRoot()
    local c = getChar()
    return c and c:FindFirstChild("HumanoidRootPart")
end

local function pushHistory()
    local r = getRoot()
    if r then
        table.insert(history, r.CFrame)
        if #history > 32 then table.remove(history, 1) end
        future = {}
    end
end

local function doTeleport(target)
    if not target then return end
    local root = getRoot()
    if not root then return end
    pushHistory()
    if state.PathWalk and state.PathTime > 0 then
        local t = TweenService:Create(root, TweenInfo.new(state.PathTime, Enum.EasingStyle.Linear), {CFrame = target})
        t:Play()
    else
        root.CFrame = target
    end
end

local function targetCFrameForMode(plr)
    local char = plr and plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end
    local cf = hrp.CFrame
    local off = state.Offset
    if state.Mode == "To" then
        return cf * CFrame.new(0, 0, -off)
    elseif state.Mode == "Behind" then
        return cf * CFrame.new(0, 0, off)
    elseif state.Mode == "InFront" then
        return cf * CFrame.new(0, 0, -off)
    elseif state.Mode == "Above" then
        return cf + Vector3.new(0, off, 0)
    elseif state.Mode == "Below" then
        return cf - Vector3.new(0, off, 0)
    elseif state.Mode == "Aim" then
        local cam = Workspace.CurrentCamera
        if not cam then return cf end
        local origin = cam.CFrame.Position
        local lookDir = cam.CFrame.LookVector
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = {getChar()}
        local result = Workspace:Raycast(origin, lookDir * 1000, params)
        local pos = result and result.Position or (origin + lookDir * 50)
        return CFrame.new(pos + Vector3.new(0, off, 0))
    end
    return cf
end

local function playerList()
    local names = {}
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer then
            local meta = plr.Name
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local myRoot = getRoot()
            if hrp and hum and myRoot then
                meta = string.format("%s  [%dm %d%%]", plr.Name,
                    math.floor((hrp.Position - myRoot.Position).Magnitude),
                    math.floor(hum.Health / math.max(hum.MaxHealth, 1) * 100))
            end
            table.insert(names, meta)
        end
    end
    if #names == 0 then table.insert(names, "(no other players)") end
    return names
end

local function findPlayerByMeta(meta)
    if not meta then return nil end
    local name = meta:match("^([^%s]+)")
    if not name or name == "(no" then return nil end
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr.Name == name then return plr end
    end
    return nil
end

-- ---------- Build UI ----------

function M.Build(tab, ctx)
    local Notify = ctx.Notify
    local UI = ctx.UI

    -- ----- Player list -----
    local plrSec = tab:AddSection("Teleport to Player")
    local picked
    local dropdown = plrSec:AddDropdown("Player", playerList(), playerList()[1], function(v) picked = v end)

    plrSec:AddButton("Refresh list", function()
        dropdown:SetOptions(playerList())
        Notify:Send("Teleport", "Player list refreshed", 2)
    end)
    plrSec:AddDropdown("TP mode", {"To","Behind","InFront","Above","Below","Aim"}, "To", function(v) state.Mode = v end)
    plrSec:AddSlider("Offset", 0, 30, 3, function(v) state.Offset = v end)
    plrSec:AddButton("Teleport", function()
        local plr = findPlayerByMeta(picked)
        local cf = plr and targetCFrameForMode(plr)
        if cf then doTeleport(cf) else Notify:Send("Teleport", "No target selected", 2) end
    end)
    plrSec:AddButton("Spectate", function()
        local plr = findPlayerByMeta(picked)
        local hum = plr and plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
        if hum then Workspace.CurrentCamera.CameraSubject = hum end
    end)
    plrSec:AddButton("Reset camera", function()
        local hum = getChar() and getChar():FindFirstChildOfClass("Humanoid")
        if hum then Workspace.CurrentCamera.CameraSubject = hum end
    end)

    -- Auto-refresh player list when players join/leave
    conns.added = Players.PlayerAdded:Connect(function() pcall(function() dropdown:SetOptions(playerList()) end) end)
    conns.left  = Players.PlayerRemoving:Connect(function() pcall(function() dropdown:SetOptions(playerList()) end) end)

    -- ----- Pathwalk -----
    local pathSec = tab:AddSection("Pathwalk")
    pathSec:AddToggle("Smooth teleport (tween)", false, function(v) state.PathWalk = v end)
    pathSec:AddSlider("Path duration (s)", 0.05, 5, 0.5, function(v) state.PathTime = v end, {Decimals = 2})

    -- ----- Waypoint slots -----
    local wpSec = tab:AddSection("Waypoints")
    for slot = 1, SLOTS do
        saved[slot] = {Name = "Slot " .. slot, CFrame = nil}
        local row = nil
        wpSec:AddTextBox("Name " .. slot, "Slot " .. slot, function(text)
            saved[slot].Name = text ~= "" and text or ("Slot " .. slot)
        end)
        wpSec:AddButton("Save slot " .. slot, function()
            local r = getRoot()
            if r then
                saved[slot].CFrame = r.CFrame
                Notify:Send("Waypoint", "Saved: " .. saved[slot].Name, 2)
            end
        end)
        wpSec:AddButton("Load slot " .. slot, function()
            if saved[slot].CFrame then
                doTeleport(saved[slot].CFrame)
            else
                Notify:Send("Waypoint", "Slot " .. slot .. " is empty", 2)
            end
        end)
        wpSec:AddButton("Clear slot " .. slot, function()
            saved[slot].CFrame = nil
            Notify:Send("Waypoint", "Cleared slot " .. slot, 2)
        end)
        wpSec:AddDivider()
    end

    -- ----- History -----
    local histSec = tab:AddSection("Teleport History")
    histSec:AddButton("Undo (back)", function()
        local last = table.remove(history)
        if last then
            local r = getRoot()
            if r then
                table.insert(future, r.CFrame)
                r.CFrame = last
            end
        else
            Notify:Send("History", "Nothing to undo", 2)
        end
    end)
    histSec:AddButton("Redo (forward)", function()
        local next_ = table.remove(future)
        if next_ then
            local r = getRoot()
            if r then
                table.insert(history, r.CFrame)
                r.CFrame = next_
            end
        else
            Notify:Send("History", "Nothing to redo", 2)
        end
    end)
    histSec:AddButton("Clear history", function()
        history = {}; future = {}
        Notify:Send("History", "Cleared", 2)
    end)

    -- ----- Click TP -----
    local clkSec = tab:AddSection("Click TP")
    clkSec:AddToggle("Hold Ctrl + click world", false, function(v) state.ClickTP = v end)
    conns.click = UserInputService.InputBegan:Connect(function(input, processed)
        if processed then return end
        if not state.ClickTP then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        if not UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then return end
        local mouse = Players.LocalPlayer:GetMouse()
        if mouse.Hit then
            doTeleport(mouse.Hit + Vector3.new(0, state.Offset, 0))
        end
    end)

    -- ----- Server -----
    local srvSec = tab:AddSection("Server")
    srvSec:AddButton("Rejoin current server", function()
        TeleportService:Teleport(game.PlaceId, Players.LocalPlayer)
    end)
    srvSec:AddButton("Server hop (lowest pop)", function()
        local ok, data = pcall(function()
            local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"):format(game.PlaceId)
            return HttpService:JSONDecode(game:HttpGet(url))
        end)
        if not (ok and data and data.data) then
            Notify:Send("Server hop", "Failed to fetch", 3); return
        end
        for _, srv in ipairs(data.data) do
            if srv.playing < srv.maxPlayers and srv.id ~= game.JobId then
                pcall(function()
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, srv.id, Players.LocalPlayer)
                end)
                return
            end
        end
        Notify:Send("Server hop", "No suitable server", 3)
    end)
end

function M.Unload()
    for _, c in pairs(conns) do pcall(function() c:Disconnect() end) end
    conns = {}
end

M.State = state
M.Saved = saved
return M

end

_modules['src/modules/hud.lua'] = function()
--[[
    HUD module — watermark, crosshair, target lock panel, off-screen arrows,
    keybind list. Uses the Drawing API; falls back to ScreenGui if missing.
]]

local Players       = game:GetService("Players")
local RunService    = game:GetService("RunService")
local Workspace     = game:GetService("Workspace")
local Stats         = game:GetService("Stats")

local M = {}

local state = {
    Watermark      = true,
    Crosshair      = false,
    XHairColor     = Color3.fromRGB(140, 100, 255),
    XHairStyle     = "Plus",   -- Plus | Dot | Circle
    XHairSize      = 6,
    XHairGap       = 3,
    XHairThickness = 1,
    XHairOutline   = true,
    TargetPanel    = true,
    OffscreenArrows= false,
    KeyOverlay     = false,
    Keys           = {},        -- [label] = "KeyName"
    Killfeed       = false,
    KillfeedMax    = 6,
    KillfeedFade   = 4,
}

local conns = {}
local elements = {}

-- Aimbot module reference for reading the current lock target
local Aimbot = nil

-- Optional override (for tests / external sources)
M.LockedTarget = nil

local function currentTarget()
    if M.LockedTarget then return M.LockedTarget end
    if Aimbot then return Aimbot.LockedTarget end
    return nil
end

local function makeGui()
    local existing = (gethui and gethui() or game:GetService("CoreGui")):FindFirstChild("ROGBLOX_HUD")
    if existing then return existing end
    local gui = Instance.new("ScreenGui")
    gui.Name = "ROGBLOX_HUD"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    if syn and syn.protect_gui then syn.protect_gui(gui) end
    gui.Parent = (gethui and gethui()) or game:GetService("CoreGui")
    return gui
end

local THEME = {
    Bg     = Color3.fromRGB(16, 16, 22),
    Panel  = Color3.fromRGB(22, 22, 30),
    Accent = Color3.fromRGB(140, 100, 255),
    Text   = Color3.fromRGB(235, 235, 245),
    Sub    = Color3.fromRGB(150, 150, 165),
    Good   = Color3.fromRGB(120, 220, 140),
    Warn   = Color3.fromRGB(255, 200,  80),
    Bad    = Color3.fromRGB(235,  90, 100),
}

-- ============================================================
-- Watermark
-- ============================================================

local function buildWatermark(gui)
    local frame = Instance.new("Frame")
    frame.Name = "Watermark"
    frame.BackgroundColor3 = THEME.Bg
    frame.BackgroundTransparency = 0.15
    frame.Position = UDim2.new(0, 12, 0, 12)
    frame.Size = UDim2.new(0, 280, 0, 24)
    frame.BorderSizePixel = 0
    frame.Parent = gui

    local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, 6); c.Parent = frame
    local s = Instance.new("UIStroke")
    s.Color = THEME.Accent; s.Thickness = 1; s.Parent = frame

    local accent = Instance.new("Frame")
    accent.BackgroundColor3 = THEME.Accent
    accent.BorderSizePixel = 0
    accent.Position = UDim2.new(0, 4, 0, 4)
    accent.Size = UDim2.new(0, 3, 1, -8)
    accent.Parent = frame
    Instance.new("UICorner", accent).CornerRadius = UDim.new(0, 2)

    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.Position = UDim2.new(0, 14, 0, 0)
    label.Size = UDim2.new(1, -18, 1, 0)
    label.Font = Enum.Font.GothamMedium
    label.Text = "ROGBLOX"
    label.TextColor3 = THEME.Text
    label.TextSize = 12
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Parent = frame

    elements.watermark = {Frame = frame, Label = label}
end

local lastTick = tick()
local fps = 0
local function updateWatermark()
    if not state.Watermark then
        if elements.watermark then elements.watermark.Frame.Visible = false end
        return
    end
    if elements.watermark then elements.watermark.Frame.Visible = true end

    local now = tick()
    local dt = now - lastTick
    lastTick = now
    fps = math.floor(0.9 * fps + 0.1 * (1 / math.max(dt, 1e-3)))
    local ping = "?"
    pcall(function()
        ping = math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue())
    end)
    local user = Players.LocalPlayer and Players.LocalPlayer.Name or "?"
    local timeStr = os.date("%H:%M:%S")
    elements.watermark.Label.Text = string.format(
        "ROGBLOX  |  %d FPS  |  %s ms  |  %s  |  %s",
        fps, tostring(ping), user, timeStr
    )
end

-- ============================================================
-- Crosshair (Drawing-based for perfect center)
-- ============================================================

local xHairParts = {}

local function clearCrosshair()
    for _, obj in pairs(xHairParts) do
        pcall(function() obj:Remove() end)
    end
    xHairParts = {}
end

local function buildCrosshair()
    clearCrosshair()
    if not (type(Drawing) == "table" and Drawing.new) then return end

    if state.XHairStyle == "Plus" then
        for i = 1, 4 do
            xHairParts[#xHairParts + 1] = Drawing.new("Line")
        end
        if state.XHairOutline then
            for i = 1, 4 do
                xHairParts[#xHairParts + 1] = Drawing.new("Line")
            end
        end
    elseif state.XHairStyle == "Dot" then
        xHairParts[#xHairParts + 1] = Drawing.new("Circle")
    elseif state.XHairStyle == "Circle" then
        xHairParts[#xHairParts + 1] = Drawing.new("Circle")
    end
end

local function updateCrosshair()
    if not state.Crosshair or #xHairParts == 0 then
        for _, obj in pairs(xHairParts) do
            if obj.Visible ~= nil then obj.Visible = false end
        end
        return
    end
    local cam = Workspace.CurrentCamera
    if not cam then return end
    local center = cam.ViewportSize / 2
    local cx, cy = center.X, center.Y
    local color = state.XHairColor
    local gap = state.XHairGap
    local sz = state.XHairSize
    local th = state.XHairThickness

    if state.XHairStyle == "Plus" then
        local segs = {
            {Vector2.new(cx - gap - sz, cy), Vector2.new(cx - gap, cy)},
            {Vector2.new(cx + gap, cy),       Vector2.new(cx + gap + sz, cy)},
            {Vector2.new(cx, cy - gap - sz), Vector2.new(cx, cy - gap)},
            {Vector2.new(cx, cy + gap),       Vector2.new(cx, cy + gap + sz)},
        }
        if state.XHairOutline then
            for i = 1, 4 do
                local line = xHairParts[i + 4]
                if line then
                    line.From = segs[i][1]; line.To = segs[i][2]
                    line.Color = Color3.new(0, 0, 0); line.Thickness = th + 2
                    line.Visible = true
                end
            end
        end
        for i = 1, 4 do
            local line = xHairParts[i]
            line.From = segs[i][1]; line.To = segs[i][2]
            line.Color = color; line.Thickness = th
            line.Visible = true
        end
    elseif state.XHairStyle == "Dot" then
        local c = xHairParts[1]
        c.Position = Vector2.new(cx, cy); c.Radius = math.max(1, th)
        c.Filled = true; c.Color = color; c.Visible = true
    elseif state.XHairStyle == "Circle" then
        local c = xHairParts[1]
        c.Position = Vector2.new(cx, cy); c.Radius = sz
        c.Thickness = th; c.Filled = false; c.Color = color
        c.NumSides = 32; c.Visible = true
    end
end

-- ============================================================
-- Target panel
-- ============================================================

local function buildTargetPanel(gui)
    local panel = Instance.new("Frame")
    panel.Name = "TargetPanel"
    panel.AnchorPoint = Vector2.new(0.5, 0)
    panel.Position = UDim2.new(0.5, 0, 0, 12)
    panel.Size = UDim2.new(0, 280, 0, 56)
    panel.BackgroundColor3 = THEME.Bg
    panel.BackgroundTransparency = 0.1
    panel.BorderSizePixel = 0
    panel.Visible = false
    panel.Parent = gui
    Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 6)
    local s = Instance.new("UIStroke"); s.Color = THEME.Bad; s.Thickness = 1; s.Parent = panel

    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1
    title.Position = UDim2.new(0, 12, 0, 6)
    title.Size = UDim2.new(1, -24, 0, 16)
    title.Font = Enum.Font.GothamBold
    title.TextColor3 = THEME.Text
    title.Text = ""
    title.TextSize = 13
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = panel

    local meta = Instance.new("TextLabel")
    meta.BackgroundTransparency = 1
    meta.Position = UDim2.new(0, 12, 0, 22)
    meta.Size = UDim2.new(1, -24, 0, 14)
    meta.Font = Enum.Font.Gotham
    meta.TextColor3 = THEME.Sub
    meta.Text = ""
    meta.TextSize = 11
    meta.TextXAlignment = Enum.TextXAlignment.Left
    meta.Parent = panel

    local hpBg = Instance.new("Frame")
    hpBg.BackgroundColor3 = THEME.Panel
    hpBg.BorderSizePixel = 0
    hpBg.Position = UDim2.new(0, 12, 1, -14)
    hpBg.Size = UDim2.new(1, -24, 0, 5)
    hpBg.Parent = panel
    Instance.new("UICorner", hpBg).CornerRadius = UDim.new(0, 2)
    local hpFill = Instance.new("Frame")
    hpFill.BackgroundColor3 = THEME.Good
    hpFill.BorderSizePixel = 0
    hpFill.Size = UDim2.new(1, 0, 1, 0)
    hpFill.Parent = hpBg
    Instance.new("UICorner", hpFill).CornerRadius = UDim.new(0, 2)

    elements.targetPanel = {Frame = panel, Title = title, Meta = meta, Hp = hpFill}
end

local function updateTargetPanel()
    local panel = elements.targetPanel
    if not panel then return end
    local target = currentTarget()
    if not (state.TargetPanel and target) then
        panel.Frame.Visible = false
        return
    end
    local char = target.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local lp = Players.LocalPlayer
    local myHrp = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
    if not (char and hum and hrp and myHrp) then panel.Frame.Visible = false; return end
    panel.Frame.Visible = true
    local hpPct = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
    panel.Title.Text = target.DisplayName
    panel.Meta.Text = string.format("%s  |  HP %d/%d  |  %dm",
        target.Name, math.floor(hum.Health + 0.5), math.floor(hum.MaxHealth + 0.5),
        math.floor((hrp.Position - myHrp.Position).Magnitude + 0.5))
    panel.Hp.Size = UDim2.new(hpPct, 0, 1, 0)
    panel.Hp.BackgroundColor3 = (hpPct > 0.5 and THEME.Good) or (hpPct > 0.25 and THEME.Warn) or THEME.Bad
end

-- ============================================================
-- Keybind overlay
-- ============================================================

local keyPanel, keyList

local function buildKeyOverlay(gui)
    if keyPanel then return end
    keyPanel = Instance.new("Frame")
    keyPanel.Name = "Keybinds"
    keyPanel.AnchorPoint = Vector2.new(1, 0)
    keyPanel.Position = UDim2.new(1, -12, 0, 40)
    keyPanel.Size = UDim2.new(0, 180, 0, 0)
    keyPanel.AutomaticSize = Enum.AutomaticSize.Y
    keyPanel.BackgroundColor3 = THEME.Bg
    keyPanel.BackgroundTransparency = 0.2
    keyPanel.BorderSizePixel = 0
    keyPanel.Visible = false
    keyPanel.Parent = gui
    Instance.new("UICorner", keyPanel).CornerRadius = UDim.new(0, 6)
    local s = Instance.new("UIStroke"); s.Color = THEME.Accent; s.Thickness = 1; s.Parent = keyPanel

    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1
    title.Size = UDim2.new(1, 0, 0, 18)
    title.Font = Enum.Font.GothamBold
    title.Text = "  hotkeys"
    title.TextColor3 = THEME.Text
    title.TextSize = 11
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = keyPanel

    keyList = Instance.new("Frame")
    keyList.BackgroundTransparency = 1
    keyList.Position = UDim2.new(0, 0, 0, 20)
    keyList.Size = UDim2.new(1, 0, 0, 0)
    keyList.AutomaticSize = Enum.AutomaticSize.Y
    keyList.Parent = keyPanel
    local layout = Instance.new("UIListLayout")
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 1)
    layout.Parent = keyList
    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 10); pad.PaddingRight = UDim.new(0, 10)
    pad.PaddingBottom = UDim.new(0, 6)
    pad.Parent = keyList
end

local function refreshKeyOverlay()
    if not keyPanel then return end
    keyPanel.Visible = state.KeyOverlay
    if not state.KeyOverlay then return end
    for _, c in ipairs(keyList:GetChildren()) do
        if c:IsA("TextLabel") then c:Destroy() end
    end
    for label, key in pairs(state.Keys) do
        local row = Instance.new("TextLabel")
        row.BackgroundTransparency = 1
        row.Size = UDim2.new(1, 0, 0, 13)
        row.Font = Enum.Font.Code
        row.TextSize = 10
        row.TextColor3 = THEME.Sub
        row.TextXAlignment = Enum.TextXAlignment.Left
        row.Text = string.format("[%s] %s", key, label)
        row.Parent = keyList
    end
end

function M.RegisterKey(label, key)
    state.Keys[label] = tostring(key)
    refreshKeyOverlay()
end

function M.UnregisterKey(label)
    state.Keys[label] = nil
    refreshKeyOverlay()
end

-- ============================================================
-- Killfeed
-- ============================================================
-- Watches every Humanoid.Died across all players. When someone dies,
-- look back through Humanoid.HealthChanged history to attribute the
-- kill to the last damage source (best-effort; many games are
-- server-authoritative so we can't see the actual killer reliably).
-- For now we just show "[died] DisplayName" entries and fade them.

local killFeed, killList

local function buildKillFeed(gui)
    if killFeed then return end
    killFeed = Instance.new("Frame")
    killFeed.Name = "Killfeed"
    killFeed.AnchorPoint = Vector2.new(1, 1)
    killFeed.Position = UDim2.new(1, -12, 1, -130)
    killFeed.Size = UDim2.new(0, 230, 0, 0)
    killFeed.AutomaticSize = Enum.AutomaticSize.Y
    killFeed.BackgroundTransparency = 1
    killFeed.Visible = false
    killFeed.Parent = gui

    killList = killFeed
    local layout = Instance.new("UIListLayout")
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 3)
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Right
    layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
    layout.Parent = killFeed
end

local function pushKillEntry(text, accent)
    if not killList then return end
    local row = Instance.new("Frame")
    row.BackgroundColor3 = THEME.Bg
    row.BackgroundTransparency = 0.1
    row.BorderSizePixel = 0
    row.Size = UDim2.new(0, 0, 0, 22)
    row.AutomaticSize = Enum.AutomaticSize.X
    row.Parent = killList
    local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, 4); c.Parent = row
    local s = Instance.new("UIStroke"); s.Color = accent or THEME.Accent; s.Thickness = 1; s.Parent = row

    local lbl = Instance.new("TextLabel")
    lbl.BackgroundTransparency = 1
    lbl.AutomaticSize = Enum.AutomaticSize.X
    lbl.Size = UDim2.new(0, 0, 1, 0)
    lbl.Font = Enum.Font.GothamMedium
    lbl.Text = "  " .. text .. "  "
    lbl.TextColor3 = THEME.Text
    lbl.TextSize = 11
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.Parent = row

    -- Cap list length
    local count = 0
    for _, ch in ipairs(killList:GetChildren()) do
        if ch:IsA("Frame") then count = count + 1 end
    end
    if count > state.KillfeedMax then
        for _, ch in ipairs(killList:GetChildren()) do
            if ch:IsA("Frame") then ch:Destroy(); break end
        end
    end

    -- Fade out and destroy
    task.delay(state.KillfeedFade, function()
        if row.Parent then
            for i = 1, 10 do
                if not row.Parent then break end
                row.BackgroundTransparency = math.clamp(0.1 + i * 0.09, 0, 1)
                s.Transparency = math.clamp(i * 0.1, 0, 1)
                lbl.TextTransparency = math.clamp(i * 0.1, 0, 1)
                task.wait(0.05)
            end
            row:Destroy()
        end
    end)
end

local function attachKillWatchers()
    -- For each current and future player, hook Humanoid.Died.
    local function watchPlayer(plr)
        local function watchChar(char)
            local hum = char:WaitForChild("Humanoid", 3)
            if not hum then return end
            local conn
            conn = hum.Died:Connect(function()
                if state.Killfeed then
                    pushKillEntry("died: " .. plr.DisplayName,
                        plr == Players.LocalPlayer and THEME.Bad or THEME.Accent)
                end
                if conn then conn:Disconnect() end
            end)
            table.insert(conns, conn)
        end
        if plr.Character then watchChar(plr.Character) end
        local addConn = plr.CharacterAdded:Connect(watchChar)
        table.insert(conns, addConn)
    end
    for _, plr in ipairs(Players:GetPlayers()) do watchPlayer(plr) end
    table.insert(conns, Players.PlayerAdded:Connect(watchPlayer))
end

-- ============================================================
-- Off-screen arrows
-- ============================================================

local arrows = {} -- [player] = Drawing.Triangle

local function getOrMakeArrow(plr)
    if arrows[plr] then return arrows[plr] end
    if not (type(Drawing) == "table" and Drawing.new) then return nil end
    local tri = Drawing.new("Triangle")
    tri.Filled = true
    tri.Color = THEME.Accent
    tri.Visible = false
    arrows[plr] = tri
    return tri
end

local function clearArrows()
    for plr, tri in pairs(arrows) do
        pcall(function() tri:Remove() end)
    end
    arrows = {}
end

local function updateArrows()
    if not state.OffscreenArrows then
        for _, tri in pairs(arrows) do tri.Visible = false end
        return
    end
    local cam = Workspace.CurrentCamera
    if not cam then return end
    local center = cam.ViewportSize / 2
    local radius = math.min(cam.ViewportSize.X, cam.ViewportSize.Y) * 0.4

    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer then
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then
                local screen, onScreen = cam:WorldToViewportPoint(hrp.Position)
                local tri = getOrMakeArrow(plr)
                if tri then
                    if onScreen then
                        tri.Visible = false
                    else
                        -- vector from center, behind = flip
                        local dir
                        if screen.Z < 0 then
                            dir = Vector2.new(-(screen.X - center.X), -(screen.Y - center.Y))
                        else
                            dir = Vector2.new(screen.X - center.X, screen.Y - center.Y)
                        end
                        if dir.Magnitude > 0 then dir = dir.Unit end
                        local tip = center + dir * radius
                        local left  = tip - dir * 14 + Vector2.new(-dir.Y, dir.X) * 7
                        local right = tip - dir * 14 + Vector2.new(dir.Y, -dir.X) * 7
                        tri.PointA = tip; tri.PointB = left; tri.PointC = right
                        tri.Visible = true
                    end
                end
            else
                if arrows[plr] then arrows[plr].Visible = false end
            end
        end
    end
end

-- ============================================================
-- Build / Unload
-- ============================================================

function M.Build(tab, ctx)
    Aimbot = ctx.Aimbot
    local gui = makeGui()
    buildWatermark(gui)
    buildTargetPanel(gui)
    buildCrosshair()

    local wm = tab:AddSection("Watermark")
    wm:AddToggle("Show watermark", true, function(v) state.Watermark = v end)

    local xh = tab:AddSection("Crosshair")
    xh:AddToggle("Enabled", false, function(v)
        state.Crosshair = v
        if v then buildCrosshair() else clearCrosshair() end
    end)
    xh:AddDropdown("Style", {"Plus","Dot","Circle"}, "Plus", function(v) state.XHairStyle = v; buildCrosshair() end)
    xh:AddSlider("Size", 1, 30, 6, function(v) state.XHairSize = v end)
    xh:AddSlider("Gap", 0, 20, 3, function(v) state.XHairGap = v end)
    xh:AddSlider("Thickness", 1, 6, 1, function(v) state.XHairThickness = v; buildCrosshair() end)
    xh:AddToggle("Outline", true, function(v) state.XHairOutline = v; buildCrosshair() end)
    xh:AddColorPicker("Color", Color3.fromRGB(140,100,255), function(v) state.XHairColor = v end)

    local tp = tab:AddSection("Target Lock Panel")
    tp:AddToggle("Show panel when locked", true, function(v) state.TargetPanel = v end)

    local oa = tab:AddSection("Off-screen Arrows")
    oa:AddToggle("Enabled", false, function(v) state.OffscreenArrows = v end)

    -- ----- Keybind overlay -----
    buildKeyOverlay(gui)
    local kb = tab:AddSection("Keybind Overlay")
    kb:AddToggle("Show active hotkeys (top-right)", false, function(v)
        state.KeyOverlay = v
        refreshKeyOverlay()
    end)
    kb:AddLabel("Default bindings shown below; modules add their own as they boot.")
    M.RegisterKey("Toggle UI", "RightCtrl")
    M.RegisterKey("Console", "Backquote")
    M.RegisterKey("Freecam", "RightShift")

    -- ----- Killfeed -----
    buildKillFeed(gui)
    attachKillWatchers()
    local kf = tab:AddSection("Killfeed")
    kf:AddToggle("Show killfeed (bottom-right)", false, function(v)
        state.Killfeed = v
        if killFeed then killFeed.Visible = v end
    end)
    kf:AddSlider("Max entries", 2, 16, 6, function(v) state.KillfeedMax = math.floor(v) end)
    kf:AddSlider("Fade after (sec)", 1, 15, 4, function(v) state.KillfeedFade = v end)
    kf:AddButton("Test entry", function()
        if state.Killfeed then pushKillEntry("test entry", THEME.Accent) end
    end)

    conns.render = RunService.RenderStepped:Connect(function()
        updateWatermark()
        updateCrosshair()
        updateTargetPanel()
        updateArrows()
    end)
end

function M.Unload()
    for _, c in pairs(conns) do pcall(function() c:Disconnect() end) end
    conns = {}
    clearCrosshair()
    clearArrows()
    local g = (gethui and gethui() or game:GetService("CoreGui")):FindFirstChild("ROGBLOX_HUD")
    if g then g:Destroy() end
end

M.State = state
return M

end

_modules['src/modules/world.lua'] = function()
--[[
    World module — Lighting overrides, fullbright, no-fog, time, FOV unlock,
    third-person zoom unlock, item ESP, chat logger.
]]

local Lighting     = game:GetService("Lighting")
local Players      = game:GetService("Players")
local RunService   = game:GetService("RunService")
local Workspace    = game:GetService("Workspace")
local StarterPlayer= game:GetService("StarterPlayer")

local M = {}
local state = {
    Fullbright = false,
    NoFog      = false,
    LockTime   = false,
    TimeOfDay  = 12,
    FOV        = 70,
    UnlockFOV  = false,
    UnlockZoom = false,
    ItemESP    = false,
    ItemKeyword = "",
    ChatLog    = false,
}

local saved
local function snapshot()
    if saved then return end
    saved = {
        Ambient = Lighting.Ambient,
        Bright = Lighting.Brightness,
        ColorShift_Top = Lighting.ColorShift_Top,
        ColorShift_Bottom = Lighting.ColorShift_Bottom,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        ClockTime = Lighting.ClockTime,
        FogEnd = Lighting.FogEnd,
        FogStart = Lighting.FogStart,
        FogColor = Lighting.FogColor,
        ZoomMin = StarterPlayer.CameraMinZoomDistance,
        ZoomMax = StarterPlayer.CameraMaxZoomDistance,
    }
end

local function restore()
    if not saved then return end
    Lighting.Ambient = saved.Ambient
    Lighting.Brightness = saved.Bright
    Lighting.ColorShift_Top = saved.ColorShift_Top
    Lighting.ColorShift_Bottom = saved.ColorShift_Bottom
    Lighting.OutdoorAmbient = saved.OutdoorAmbient
    Lighting.ClockTime = saved.ClockTime
    Lighting.FogEnd = saved.FogEnd
    Lighting.FogStart = saved.FogStart
    Lighting.FogColor = saved.FogColor
    pcall(function()
        StarterPlayer.CameraMinZoomDistance = saved.ZoomMin
        StarterPlayer.CameraMaxZoomDistance = saved.ZoomMax
    end)
end

local conns = {}

local function applyLighting()
    if state.Fullbright then
        Lighting.Ambient = Color3.fromRGB(255, 255, 255)
        Lighting.Brightness = 2
        Lighting.ColorShift_Top = Color3.fromRGB(255, 255, 255)
        Lighting.ColorShift_Bottom = Color3.fromRGB(255, 255, 255)
        Lighting.OutdoorAmbient = Color3.fromRGB(255, 255, 255)
    end
    if state.NoFog then
        Lighting.FogEnd = 1e9
        Lighting.FogStart = 1e9
    end
    if state.LockTime then
        Lighting.ClockTime = state.TimeOfDay
    end
end

local function applyFOV()
    local cam = Workspace.CurrentCamera
    if cam and state.UnlockFOV then
        cam.FieldOfView = state.FOV
    end
end

local function applyZoom()
    if state.UnlockZoom then
        local lp = Players.LocalPlayer
        pcall(function()
            StarterPlayer.CameraMinZoomDistance = 0.5
            StarterPlayer.CameraMaxZoomDistance = 1000
            if lp then
                lp.CameraMinZoomDistance = 0.5
                lp.CameraMaxZoomDistance = 1000
            end
        end)
    end
end

-- ---------- Item ESP ----------

local itemTags = {}
local function clearItemTags()
    for _, bb in pairs(itemTags) do bb:Destroy() end
    itemTags = {}
end

local function scanItems()
    if not state.ItemESP then clearItemTags(); return end
    local needle = state.ItemKeyword:lower()
    local seen = {}
    for _, obj in ipairs(Workspace:GetDescendants()) do
        if obj:IsA("Tool") or obj:IsA("Model") then
            local name = obj.Name:lower()
            if needle ~= "" and name:find(needle, 1, true) then
                seen[obj] = true
                if not itemTags[obj] then
                    local part = obj:IsA("Tool") and obj:FindFirstChildOfClass("Part") or obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")
                    if part then
                        local bb = Instance.new("BillboardGui")
                        bb.AlwaysOnTop = true
                        bb.Size = UDim2.new(0, 100, 0, 20)
                        bb.StudsOffset = Vector3.new(0, 2, 0)
                        bb.Adornee = part
                        bb.Parent = part
                        local t = Instance.new("TextLabel")
                        t.BackgroundTransparency = 1
                        t.Size = UDim2.new(1, 0, 1, 0)
                        t.Font = Enum.Font.GothamBold
                        t.Text = obj.Name
                        t.TextColor3 = Color3.fromRGB(255, 200, 80)
                        t.TextStrokeTransparency = 0
                        t.TextSize = 13
                        t.Parent = bb
                        itemTags[obj] = bb
                    end
                end
            end
        end
    end
    for obj, bb in pairs(itemTags) do
        if not seen[obj] then bb:Destroy(); itemTags[obj] = nil end
    end
end

-- ---------- Chat logger ----------

local chatHookSetup = false
local chatHookSaved = {}    -- snapshot for restoration on Unload
local function setupChatLog()
    if chatHookSetup then return end
    chatHookSetup = true
    local function log(speaker, msg)
        if state.ChatLog then
            print(("[ROGBLOX chat] %s: %s"):format(speaker, msg))
        end
    end
    -- Legacy: connection-based, auto-cleans with our conns table
    pcall(function()
        local re = game:GetService("ReplicatedStorage"):WaitForChild("DefaultChatSystemChatEvents", 3)
        if re then
            conns.legacyChat = re.OnMessageDoneFiltering.OnClientEvent:Connect(function(data)
                log(data.FromSpeaker or "?", data.Message or "")
            end)
        end
    end)
    -- New TextChatService: we replace OnIncomingMessage; save the old
    -- handler so Unload can restore it (a chained game-side handler
    -- would otherwise stay clobbered).
    pcall(function()
        local tcs = game:GetService("TextChatService")
        chatHookSaved.prevOnIncoming = tcs.OnIncomingMessage
        chatHookSaved.tcs = tcs
        tcs.OnIncomingMessage = function(message)
            local props = Instance.new("TextChatMessageProperties")
            log(message.TextSource and message.TextSource.Name or "?", message.Text)
            return props
        end
    end)
end

function M.Build(tab, ctx)
    snapshot()
    setupChatLog()

    local lightSec = tab:AddSection("Lighting")
    lightSec:AddToggle("Fullbright", false, function(v) state.Fullbright = v if not v then restore(); saved = nil; snapshot() end end)
    lightSec:AddToggle("No fog", false, function(v) state.NoFog = v if not v then restore(); saved = nil; snapshot() end end)
    lightSec:AddToggle("Lock time", false, function(v) state.LockTime = v end)
    lightSec:AddSlider("Time of day", 0, 24, 12, function(v) state.TimeOfDay = v end)
    lightSec:AddButton("Restore defaults", function() restore() end)

    local camSec = tab:AddSection("Camera")
    camSec:AddToggle("Unlock FOV", false, function(v) state.UnlockFOV = v end)
    camSec:AddSlider("FOV", 30, 120, 70, function(v) state.FOV = v end)
    camSec:AddToggle("Unlock zoom", false, function(v) state.UnlockZoom = v applyZoom() end)

    local itemSec = tab:AddSection("Item ESP")
    itemSec:AddToggle("Enabled", false, function(v) state.ItemESP = v end)
    itemSec:AddTextBox("Keyword filter", "e.g. ammo, gun, key", function(v) state.ItemKeyword = v end)
    itemSec:AddButton("Rescan", function() scanItems() end)

    local chatSec = tab:AddSection("Chat Logger")
    chatSec:AddToggle("Log to console", false, function(v) state.ChatLog = v end)

    conns.light = RunService.Heartbeat:Connect(applyLighting)
    conns.fov = RunService.RenderStepped:Connect(applyFOV)
    conns.items = RunService.Heartbeat:Connect(function()
        if state.ItemESP and tick() % 1 < 0.04 then scanItems() end
    end)
end

function M.Unload()
    for _, c in pairs(conns) do if c.Disconnect then pcall(function() c:Disconnect() end) end end
    conns = {}
    clearItemTags()
    restore()
    if chatHookSetup and chatHookSaved.tcs then
        pcall(function()
            chatHookSaved.tcs.OnIncomingMessage = chatHookSaved.prevOnIncoming
        end)
        chatHookSetup = false
        chatHookSaved = {}
    end
end

M.State = state
return M

end

_modules['src/modules/autofarm.lua'] = function()
--[[
    Auto-farm / auto-clicker / auto-attack module.
    Generic primitives — concrete farms are usually game-specific.
]]

local Players          = game:GetService("Players")
local RunService       = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace        = game:GetService("Workspace")

local M = {}
local state = {
    AutoClick    = false,
    CPS          = 16,
    AutoAttack   = false,         -- swing Tool every N seconds
    AttackRate   = 0.4,
    NearestNPC   = false,         -- walk to nearest NPC repeatedly
    NPCRange     = 80,
    NPCKeyword   = "",
}

local conns = {}
local alive = false               -- gate that lets background loops exit on Unload

local function getRoot()
    local lp = Players.LocalPlayer
    local c = lp and lp.Character
    return c and c:FindFirstChild("HumanoidRootPart")
end

local function findNearestNPC()
    local root = getRoot()
    if not root then return nil end
    local needle = state.NPCKeyword:lower()
    local best, bestDist
    for _, obj in ipairs(Workspace:GetDescendants()) do
        if obj:IsA("Humanoid") and obj.Health > 0 then
            local model = obj.Parent
            local hrp = model and (model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso"))
            local plr = model and Players:GetPlayerFromCharacter(model)
            if hrp and not plr then
                if needle == "" or model.Name:lower():find(needle, 1, true) then
                    local d = (hrp.Position - root.Position).Magnitude
                    if d <= state.NPCRange and (not bestDist or d < bestDist) then
                        best, bestDist = hrp, d
                    end
                end
            end
        end
    end
    return best
end

function M.Build(tab, ctx)
    alive = true
    local clickSec = tab:AddSection("Auto Clicker")
    clickSec:AddToggle("Enabled", false, function(v) state.AutoClick = v end)
    clickSec:AddSlider("CPS", 1, 60, 16, function(v) state.CPS = v end)
    clickSec:AddLabel("Tip: most games block mouse1press detection; if it doesn't fire, set a hotkey.")

    task.spawn(function()
        while alive do
            if state.AutoClick then
                pcall(function()
                    if mouse1click then mouse1click()
                    elseif mouse1press and mouse1release then mouse1press(); mouse1release() end
                end)
                task.wait(1 / math.max(state.CPS, 1))
            else
                task.wait(0.1)
            end
        end
    end)

    local attackSec = tab:AddSection("Auto Attack")
    attackSec:AddToggle("Activate equipped tool", false, function(v) state.AutoAttack = v end)
    attackSec:AddSlider("Rate (sec)", 0.05, 5, 0.4, function(v) state.AttackRate = v end)
    task.spawn(function()
        while alive do
            if state.AutoAttack then
                local lp = Players.LocalPlayer
                local char = lp and lp.Character
                if char then
                    for _, tool in ipairs(char:GetChildren()) do
                        if tool:IsA("Tool") then
                            pcall(function() tool:Activate() end)
                        end
                    end
                end
                task.wait(state.AttackRate)
            else
                task.wait(0.1)
            end
        end
    end)

    local farmSec = tab:AddSection("NPC Tracker")
    farmSec:AddToggle("Track nearest NPC", false, function(v) state.NearestNPC = v end)
    farmSec:AddSlider("Range", 5, 500, 80, function(v) state.NPCRange = v end)
    farmSec:AddTextBox("Name filter", "(blank = any)", function(v) state.NPCKeyword = v end)
    farmSec:AddButton("Teleport to nearest", function()
        local t = findNearestNPC()
        local root = getRoot()
        if t and root then root.CFrame = t.CFrame + Vector3.new(0, 0, 3) end
    end)

    conns.farm = RunService.Heartbeat:Connect(function()
        if not state.NearestNPC then return end
        local t = findNearestNPC()
        local root = getRoot()
        if t and root then
            local hum = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:MoveTo(t.Position)
            end
        end
    end)
end

function M.Unload()
    alive = false
    state.AutoClick = false
    state.AutoAttack = false
    state.NearestNPC = false
    for _, c in pairs(conns) do if c.Disconnect then pcall(function() c:Disconnect() end) end end
    conns = {}
end

M.State = state
return M

end

